(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["sk"] = {"ui":{"skip":"Preskočiť na obsah","back":"← Späť na AI-gile","lang.button":"Jazyk: {name}","lang.dialog":"Vyber jazyk","lang.search":"Hľadať jazyky","lang.none":"Žiadny jazyk nezodpovedá","lang.notYet":"{name} ešte nie je preložený","theme.aria":"Prepnúť tému: svetlá, tmavá alebo čierna","theme.toLight":"Prepnúť na svetlú tému","theme.toDark":"Prepnúť na tmavú tému","theme.toBlack":"Prepnúť na čiernu tému (skutočná čierna, šetrná k OLED obrazovkám)","words.underline":"Podčiarknuť tieto slová na stránke","words.underlineHelp":"Prejdi myšou nad bodkovane podčiarknuté slovo alebo naň ťukni a uvidíš, čo znamená.","words.col.todo":"Karty vybrané na teraz: tím sa do nich pustí ako ďalšie.","words.col.doing":"Na tejto karte práve pracuje AI.","words.col.review":"Jedna AI dokončila prácu; skôr než sa dostane k tebe, skontroluje ju iná.","words.col.verify":"Čaká na teba: vyskúšaj to a povedz, či to funguje.","words.col.team":"Tvoje poznámky alebo odpovede, ktoré čakajú, kým ich tím prevezme.","words.col.done":"Hotové a prijaté.","index.title":"AI-gile: tvoj AI vývojársky tím na jednej tabuli","index.description":"AI-gile je kanban tabuľa pre tímy AI programátorov. Pracujú, kým spíš; ty dostaneš jednu krátku kôpku vecí na rozhodnutie, otestovanie a schválenie.","hero.logoAlt":"Ikona tabule AI-gile","hero.h1.html":"Tvoj AI vývojársky tím na jednej&nbsp;tabuli.","hero.alpha":"🐣 Uzavretá pre-alfa","hero.alphaTitle":"Skorá a nedokončená verzia: vďaka, že ju skúšaš!","hero.lede":"Stavajú, kým spíš. Ráno ťa čaká jedna krátka kôpka: pár otázok, pár vecí na otestovanie, jeden-dva fialové diamanty. Klikneš, schválíš a vrátiš sa ku káve.","dl.windows":"Aplikácia pre Windows","dl.browser":"Spustiť v prehliadači","dl.messenger":"📱 Messenger do mobilu","dl.soon":"Čoskoro","dl.notify":"🔔 Daj mi vedieť, keď sa otvorí","dl.notifySmall":"Alfa alebo beta","hero.secondary":"Agilne, ale tím nikdy nepotrebuje ranný stand-up s kávou. (Stand-upy aj tak robia.)","pitch.h2":"AI-gile v toľkých slovách, koľko chceš","pitch.lede":"Vyber dĺžku, od jedného slova po 144. Každá dĺžka je samostatný popis napísaný práve pre ňu. Potiahni posuvník alebo použi šípky.","pitch.rangeLabel":"Dĺžka v slovách","pitch.dice":"🎲 iná verzia","pitch.words.one":"{n} slovo","pitch.words.other":"{n} slov","pitch.letters.one":"{n} písmeno","pitch.letters.other":"{n} písmen","pitch.chars.one":"{n} znak","pitch.chars.other":"{n} znakov","count.line.html.one":"{n} karta je práve na tabuli","count.line.html.other":"{n} kariet je práve na tabuli","people.humans.html.one":"👥 {n} človek","people.humans.html.other":"👥 {n} ľudí","people.agents.html.one":"🤖 {n} agent","people.agents.html.other":"🤖 {n} agentov","people.working.html.one":"⚡ {n} práve pri práci","people.working.html.other":"⚡ {n} práve pri práci","pre.title":"AI-gile: niečo sa tu stavia","pre.description":"Niečo sa tu stavia: tabuľa, na ktorej AI tímy stavajú, o čo ich požiadaš, a popritom ťa učia. Zatiaľ uzavretá pre-alfa s priateľmi.","pre.h1":"Niečo sa tu stavia. 🤫","pre.line":"Tabuľa, na ktorej AI tímy stavajú, o čo ich požiadaš, a popritom ťa učia. Zatiaľ uzavretá pre-alfa s priateľmi.","pre.btn":"🔔 Daj mi vedieť, keď sa otvorí","pre.peek":"Za sklom: skutočná tabuľa, naživo. Každá karta je farebný pásik.","pre.peekFake":"Za sklom: takto vyzerá tabuľa v akcii.","pre.night":"🌙 Nočný strážnik má velenie · 😴 človek odpočíva","features.aria":"Čo robí","f.pile.h":"Jedna kôpka pre teba","f.pile.html":"<b>Pre teba</b> obsahuje všetko, čo čaká na teba, naprieč všetkými projektmi: otázky, veci na otestovanie, úlohy, ktoré zvládne len človek. Tvoj rad ti povie, čo je na rade a koľko to potrvá.","f.sleep.h":"Tímy, ktoré pracujú, kým spíš","f.sleep.p":"Každý projekt má vedúceho a tím AI agentov. Napíš komentár ku karte a tím sa zobudí, odvedie prácu a vráti ti ju s krokmi, ktoré zvládne aj unavený človek.","f.tester.h":"Najprv kontroluje AI tester","f.tester.p":"Skôr než sa čokoľvek dostane k tebe, tester prejde kroky v kópii aplikácie a ukáže, čo videl, so snímkou obrazovky. Prelistuj tie, čo prešli, a schváľ jedným klikom.","f.proof.h":"Dôkazy, nie sľuby","f.proof.p":"Každé odovzdanie ukazuje, čo sa zmenilo: súbory, rozdiely, snímky obrazovky. Nemusíš otvárať každú aplikáciu, aby si zistil, či je hotovo.","f.chat.h":"Chat so svojimi vedúcimi","f.chat.p":"Lišta ako na Discorde: jedna ikona na projekt, fialové diamanty pri tom, čo potrebuje teba. Napíš vedúcemu nápad; premení ho na karty a plán s tlačidlom ✅ Ísť na to.","f.tidy.h":"Upratuje si po sebe","f.tidy.p":"Súvisiace karty sa zlúčia, zmätené názvy sa opravia a kontrola tokenov udržiava kód štíhly. Menej vecí na prepínanie, menej na premýšľanie.","f.private.h":"Tvoje, na tvojom počítači","f.private.li1":"Tabuľa beží na tvojom vlastnom stroji a odpovedá len tebe.","f.private.li2":"Súkromné správy medzi ľuďmi sú šifrované end-to-end.","f.private.li3":"Žiadne účty, žiadne sledovače, žiadne cookies.","f.lang.h":"Vo tvojom jazyku","f.lang.p":"Vyše 120 jazykov, od holandčiny, walesčiny a japončiny až po pirátčinu, Yodu a klingončinu, s rýchlym prepnutím späť do angličtiny pre odborné výrazy.","f.service.h":"Od nápadu k skutočnej službe","f.service.p":"Postavil si s AI niečo, čo ľudia teraz používajú? Označ to ako službu a board ti pomôže dobre ju prevádzkovať: kontroly dostupnosti, verejná stránka stavu, incidenty s rozborom, zmeny, ktoré potrebujú Go, zálohy kontrolované každý deň. Pomocník ťa naučí každý krok počas práce.","msgr.h2":"AI-gile Messenger: tvoj tím vo vrecku","msgr.p1":"Rozprávaj sa so svojím AI tímom bez otvárania boardu. Chatuj s vedúcimi projektov aj s kamarátmi, pozri si testovacie kroky karty a odpovedz na ne, všetko z mobilu.","msgr.p2":"Na spárovanie naskenuj QR kód na svojom boarde. Prvýkrát? Priateľský demo chat ťa všetkým prevedie.","msgr.when":"Najprv Android, potom webová verzia pre mobily a iPhone.","msgr.who":"Tvoj vedúci projektu","msgr.b1":"Oprava tmavého režimu je hotová. Chceš testovacie kroky?","msgr.b2":"Áno, prosím!","msgr.b3":"1. Otvor Nastavenia. 2. Vyber Tmavý. Vyzerá to dobre?","tl.aria":"Časová os od prvého rozhovoru po plán","tl.h2":"Od prvého rozhovoru po to, čo príde","tl.lede":"Skutočné dátumy a časy vo tvojom časovom pásme. Po dnešku je to plán, bez sľubovaných dátumov.","tl.today":"Dnes","tl.planned":"plánované","tl.doing":"rozrobené","tl.cards.one":"{n} karta","tl.cards.other":"{n} kariet","join.h2":"Pridaj sa","join.lede":"AI-gile stavia bradatý čudák s AuDHD a pár bojmi o duševné zdravie a k tomu veľa trpezlivých agentov. Zatiaľ je súkromné, v uzavretej alfe s priateľmi. Chceš si ho vyskúšať, keď sa otvorí?","join.btn":"Prejaviť záujem","join.small":"Napíšeme ti e-mail, nič iné","footer.tag":"AI-gile. Žiadne sledovače, žiadne cookies, žiadna stand-up káva.","footer.licence":"Podniková licencia","footer.status":"Stav","footer.privacy":"Čo uchovávame","footer.thanks":"Hovory vďaka ChilledChat","form.sending":"Odosiela sa…","form.failed":"Nevyšlo to: skús to neskôr.","form.offline":"AI-gile sa nepodarilo kontaktovať: skús to neskôr.","form.keep":"Použijeme to len na to, aby sme ti odpovedali, potom to zmažeme. Žiadne sledovače, žiadne cookies.","form.keepLink":"Čo uchovávame","interest.title":"AI-gile: daj mi vedieť, keď sa otvorí alfa","interest.description":"Nechaj nám e-mail a dáme ti vedieť, keď sa otvorí uzavretá alfa alebo beta AI-gile.","interest.h1":"🔔 Daj mi vedieť, keď sa otvorí","interest.lede":"AI-gile je v uzavretej pre-alfe. Nechaj nám e-mail a napíšeme ti raz, keď bude pre teba miesto.","interest.email":"Tvoj e-mail","interest.which":"Ktorý test?","interest.alpha":"Uzavretá alfa: skorá, drsná, veľa zmien","interest.beta":"Beta: stabilnejšia, neskôr","interest.both":"Ktorýkoľvek, podľa toho, čo bude skôr","interest.submit":"Zapísať ma do zoznamu","interest.thanks":"Vďaka! Si v zozname.","licence.title":"AI-gile: podniková licencia","licence.description":"Používaš AI-gile vo svojej firme? Požiadaj o bezplatnú podnikovú licenciu.","licence.h1":"📜 Podniková licencia","licence.lede":"Používaš AI-gile v práci? Povedz nám, kto si a čo robíš. Ak to robí svet lepším, licencia je zadarmo.","licence.company":"Firma","licence.website":"Web","licence.what":"Čo robíš","licence.how":"Ako to pomáha svetu","licence.email":"E-mail","licence.submit":"Požiadať","licence.thanks":"Vďaka! Odpovieme e-mailom.","status.title":"Stav AI-gile","status.h1":"Stav AI-gile","status.quiet":"Všetko pokojné","status.intro":"Funguje AI-gile práve teraz? Táto stránka každých 5 minút kontroluje web, zdieľanie tabúľ, hovory a sťahovanie.","status.up":"Funguje (odpoveď za {ms} ms)","status.slow":"Bez odpovede pri poslednej kontrole, skúšam znova","status.down":"Nefunguje: bez odpovede pri posledných dvoch kontrolách","status.svc.web":"Web","status.svc.web.offers":"Táto stránka: čo je AI-gile a formulár na prejavenie záujmu","status.svc.boards":"Zdieľanie tabúľ","status.svc.boards.offers":"Verejné tabule, správy medzi priateľmi a pozvánky","status.svc.calls":"Hovory","status.svc.calls.offers":"Hlas, video a zdieľanie obrazovky v AI-gile","status.svc.download":"Sťahovanie","status.svc.download.offers":"Inštalátor pre Windows a odkazy na pozvánky","status.checking":"Kontroluje sa…","status.offline":"Služba stavu je teraz nedostupná (skúšam znova)","status.updated":"aktualizované {ago}","status.justNow":"práve teraz","status.min":"pred {n} min","status.hours":"pred {n} h","status.days":"pred {n} d","privacy.title":"AI-gile: čo uchovávame","privacy.h1":"Čo uchovávame","privacy.lede":"Stručne: len to, čo nám pošleš, a nie nadlho.","privacy.only":"Len to, čo nám pošleš: to, čo napíšeš do formulára, napríklad svoj e-mail. Nič iné o tebe.","privacy.sealed":"Je to zapečatené, takže náš server to nedokáže prečítať: v tvojom prehliadači ešte pred odoslaním (v staršom prehliadači hneď po doručení). Otvoriť to vie len naša vlastná tabuľa.","privacy.server":"Zo servera sa to zmaže hneď, ako to dorazí na našu tabuľu. Čokoľvek, čo tam zostane aj po 30 dňoch, sa aj tak zmaže.","privacy.board":"Na našej tabuli to necháme len dovtedy, kým ti neodpovieme, potom to zmažeme aj tam.","privacy.none":"Žiadne sledovače, žiadne cookies, žiadna analytika.","privacy.local":"Tvoj jazyk a voľba svetlej či tmavej témy zostávajú v tvojom prehliadači. Nikdy sa nám neposielajú.","privacy.ask":"Chceš, aby to zmizlo skôr? Odpovedz na náš e-mail a napíš nám to.","live.h2":"Sledujte, ako sa to stavia, naživo","live.caption":"Každá karta je skrytá: vidíte tvar práce, nie slová.","live.watching.one":"naživo: sleduje {n}","live.watching.other":"naživo: sledujú {n}","live.last.now":"Posledná karta presunutá práve teraz","live.last.min.one":"Posledná karta presunutá pred {n} minútou","live.last.min.other":"Posledná karta presunutá pred {n} minútami","live.last.hour.one":"Posledná karta presunutá pred {n} hodinou","live.last.hour.other":"Posledná karta presunutá pred {n} hodinami","live.last.day.one":"Posledná karta presunutá pred {n} dňom","live.last.day.other":"Posledná karta presunutá pred {n} dňami","live.offline":"Živá tabuľa si dáva pauzu. Skúste to čoskoro znova.","live.cols":"Backlog|Na urobenie|Rozrobené|Tím kontroluje|Čaká na tvoj test|Pre tím|Hotovo","pitch.words.few":"{n} slová","pitch.words.many":"{n} slova","pitch.letters.few":"{n} písmená","pitch.letters.many":"{n} písmena","pitch.chars.few":"{n} znaky","pitch.chars.many":"{n} znaku","count.line.html.few":"{n} karty sú práve na tabuli","count.line.html.many":"{n} karty je práve na tabuli","tl.cards.few":"{n} karty","tl.cards.many":"{n} karty","live.last.min.few":"Posledná karta presunutá pred {n} minútami","live.last.min.many":"Posledná karta presunutá pred {n} minúty","live.last.hour.few":"Posledná karta presunutá pred {n} hodinami","live.last.hour.many":"Posledná karta presunutá pred {n} hodiny","live.last.day.few":"Posledná karta presunutá pred {n} dňami","live.last.day.many":"Posledná karta presunutá pred {n} dňa","footer.models":"AI-gile spúšťa AI modely za teba. To, čo hovoria a robia, je ich vec, takže si to over, skôr než tomu uveríš.","privacy.ai.h":"Časť s AI","privacy.ai.models":"AI-gile je board. Prácu robia AI modely od iných firiem, ako Claude, Codex a Gemini, na tvojich vlastných účtoch.","privacy.ai.check":"To, čo píšu a robia, pochádza od nich a môže byť nesprávne. Over si to, skôr než sa na to spoľahneš alebo to nasadíš.","privacy.ai.files":"Menia súbory a spúšťajú príkazy v priečinkoch, ktoré pripojíš. Rob si zálohu.","privacy.ai.send":"To, čo modelu dáš, ide firme, ktorá ho prevádzkuje, podľa jej podmienok. Platia podmienky a ceny každej z nich.","privacy.ai.asis":"AI-gile je skorá testovacia verzia, poskytovaná tak, ako je."},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Roboti.","Delegované."]},{"n":2,"texts":["Robotický kanban.","Agenti, usporiadaní.","Nápady hotovo."]},{"n":3,"texts":["Kanban pre robotov.","Z nápadov funkcie.","Bezplatný kanban agentov."]},{"n":5,"texts":["Kanban tabuľa, ktorú vedú agenti.","Ty píšeš karty. Agenti staviajú.","Zadarmo, lokálne, testované, trochu bláznivé."]},{"n":8,"texts":["Bezplatná kanban tabuľa, na ktorej pracujú AI agenti.","Napíš nápad. Agenti ho postavia. Ty ho schváliš.","Agilita pre jedného človeka a veľa trpezlivých robotov."]},{"n":13,"texts":["Kanban tabuľa na tvojom počítači, kde si karty preberajú AI agenti a pracujú na nich.","Napíš nápad. Tím agentov ho postaví. Tester ho skontroluje. Ty povieš áno.","Zadarmo, bez účtov a sledovačov: tabuľa, zopár robotov a ty ako šéf."]},{"n":21,"texts":["AI-gile je kanban tabuľa na prácu s AI agentmi, ktorí programujú. Oni preberajú karty a ty ich testuješ a schvaľuješ.","Každý projekt dostane vedúceho a tím AI agentov. Napíš komentár k ľubovoľnej karte a tím sa pustí do práce.","Bezplatná osobná tabuľa úloh, ktorá beží na tvojom vlastnom počítači. Pracujú na nej roboti. Povedať áno môžeš len ty."]},{"n":34,"texts":["Nápady dáš na tabuľu. Tím AI agentov ich premení na fungujúce funkcie, otestuje ich a vráti ti ich s krokmi na vyskúšanie. Nič nie je hotové, kým to nepovieš ty.","AI-gile je domáca kanban tabuľa, ktorú Rich postavil s veľkou pomocou agentov, ktorých dnes sama riadi. Je zadarmo, beží na tvojom počítači a zdieľa sa s priateľmi, nepredáva sa.","Predstav si obyčajnú kanban tabuľu so stĺpcami od Backlogu po Hotovo, len karty preberajú AI agenti. Hlásia pokrok, pýtajú sa, keď uviaznu, a vždy počkajú na tvoj súhlas."]},{"n":55,"texts":["AI-gile je kanban tabuľa, kde tím tvoria AI agenti. Každý projekt má vedúceho, ktorý plánuje prácu, a pomocníkov, ktorí ju stavajú. Keď je funkcia hotová, AI tester ju vyskúša a urobí snímku obrazovky, potom pristane na tvojej kôpke. Schváľ ju, alebo napíš komentár a prepracujú ju.","Začalo to ako spôsob, ako si jeden človek stráži veľa AI programátorských relácií naraz, a vyrástla z toho poriadna tabuľa. Beží na tvojom stroji, nepotrebuje účet a nemá sledovače. Pre priateľov a zvedavcov je zadarmo. Je aj nedokončená, takže počítaj s hranami a občasným prekvapením.","Tu je úprimná verzia. Nápady musíš stále mať ty a výsledky musíš stále skontrolovať ty. AI-gile robí všetko, čo je medzi tým: drží karty v poriadku, zobudí správneho agenta, keď napíšeš komentár, presne ukáže, čo sa zmenilo, a všetko ti zloží do jednej krátkej kôpky, ktorú zvládneš prejsť aj pri raňajšej káve."]},{"n":89,"texts":["AI-gile je bezplatná kanban tabuľa, ktorú spúšťaš na vlastnom počítači. Namiesto ľudí má každý projekt tím AI agentov: vedúceho, ktorý tvoje nápady premení na karty a plán, a pomocníkov, ktorí karty preberajú podľa priority. Keď je niečo postavené, AI tester prejde testovacie kroky a ukáže ti, čo videl. Potom to čaká v jednej kôpke s názvom Pre teba. Schválíš to, alebo napíšeš komentár a tím to skúsi znova. Do stĺpca Hotovo sa nič nedostane bez teba.","Niekoľko vecí, ktoré by ťa mohli prekvapiť. Nočná hliadka dopĺňa stĺpec Na urobenie, kým spíš, a vyberá karty, ktoré od teba nepotrebujú odpoveď. Počítadlo tokenov ukazuje, koľko agenti minuli dnes a tento týždeň, a Režim bez tokenov im povie, aby prestali míňať. S priateľmi si môžeš písať a súkromné správy sú šifrované end-to-end. Tabuľa hovorí približne 120 jazykmi, aj holandsky, flámsky, pirátsky a klingonsky. Nič z toho nestojí ani cent a nikto sa ti to ani nesnaží predať.","AI-gile je malý osobný projekt, nie firma. Rich chcel spravovať niekoľko AI programátorských projektov bez otvárania každej aplikácie, tak spolu s agentmi postavil tabuľu a potom na nej postavil zvyšok seba samej. Je v uzavretej pre-alfe, čo znamená, že pre hŕstku priateľov funguje, väčšinou. Nemá cenník, newsletter ani plán rastu. Beží na tvojom počítači, bez účtov a bez sledovačov. Ak ti to znie užitočne, môžeš si vyžiadať vyskúšanie, keď sa trochu viac otvorí. Napíšeme ti jediný e-mail, nič iné."]},{"n":144,"texts":["AI-gile je kanban tabuľa pre jedného človeka a veľa AI agentov. Beží na tvojom vlastnom počítači a je úplne zadarmo. Pridáš projekty a každý dostane vedúceho a malý tím. S vedúcim chatuješ, trochu ako na Discorde, a opíšeš nápad; vedúci z neho spraví karty a plán a potom čaká, kým stlačíš Ísť na to. Tím prechádza karty podľa priority pomocou jednoduchého príkazového riadku vytvoreného pre jazykové modely. Skôr než sa čokoľvek vráti k tebe, AI tester prejde kroky v kópii aplikácie a priloží snímku obrazovky. Hotová práca pristane na tvojej kôpke so zmenenými súbormi a rozdielmi. Schválíš ju, alebo zanecháš komentár a tím sa zobudí a skúsi to znova. Kartu do Hotovo môžeš presunúť len ty.","Deň s AI-gile, zhruba. Večer necháš pár komentárov: toto tlačidlo je na zlom mieste, ten zoznam by mal byť zoradený, mohli by sme mať tmavý režim. Ideš spať. Agenti si prečítajú komentáre, urobia zmeny, otestujú ich a vrátia ti ich. Ak Na urobenie vyschne, nočná hliadka ho doplní z backlogu kartami, ktoré od teba nepotrebujú odpoveď. Ráno je tu jedna krátka kôpka: pár otázok a zopár vecí na vyskúšanie, každá s krokmi, ktoré zvládne aj rozospatý človek, a so snímkou, že to funguje. Prekliknieš sa, schváliš dobré a zvyšok pošleš späť. Počítadlo tokenov ukáže, čo to všetko stálo, a Režim bez tokenov je tu na skromnejšie týždne. Potom si dáš raňajky, v ktorých ti agenti zatiaľ pomôcť nevedia.","Najprv to, čo AI-gile nie je. Nie je to startup, nie je na predaj a nikto nezbiera tvoje dáta. Je to bezplatná tabuľa, ktorá beží na tvojom počítači, bez účtov, bez sledovačov a bez cookies. A čo to je: jedno prehľadné miesto, kde vidíš všetky AI programátorské projekty naraz, s tímom agentov, ktorý robí karty, a tebou, ktorý rozhoduješ. Zlučuje súvisiace karty, opravuje zmätené názvy a pozerá, aby kód zostal štíhly. Hovorí približne 120 jazykmi, od holandčiny a flámčiny po pirátčinu a klingončinu. Priatelia si môžu písať súkromne a šifrovane. Postavil ho Rich s veľkým počtom trpezlivých agentov, väčšinou za pomoci seba samého. Je v uzavretej pre-alfe, takže miestami drhne. Ak ti to znie zábavne, pekne požiadaj a možno sa dostaneš dnu skôr."]}],"quips":{"1":"Jedno slovo. Odvážne. Možno príliš.","3":"Tri slová. Už teraz úprimnejšie ako väčšina produktových stránok.","8":"Osem slov. Stále kratšie ako stand-up.","21":"Dĺžky sú mimochodom story pointy. Samozrejme, že sú.","55":"Päťdesiatpäť slov. Kým si to čítal, dokončili sa dve karty.","144":"To je tá dlhá. 233 neexistuje. Agenti išli spať."}},"timeline":{"first-idea.name":"Prvý nápad","first-idea.line":"Úplne prvý rozhovor, ešte pred prvým riadkom kódu.","first-board.name":"Prvá tabuľa","first-board.line":"Tabuľa, ktorá sleduje vlastnú stavbu: karty, stĺpce, presúvanie, projekty.","team-roles.name":"Tím a roly","team-roles.line":"Profily agentov, šablóny tímov, priestory a kto robí čo.","install.name":"Inštalácia a vydania","install.line":"Zip, ktorý si nainštaluje aj kamarát, samoaktualizácie, kanály a návrat späť.","usage-saver.name":"Šetrič spotreby","usage-saver.line":"Zmeraj, koľko behy stoja, udržuj kód štíhly, šetri svoj limit.","friends.name":"Priatelia a zdieľanie","friends.line":"Súkromné správy, šifrované relé, pozvánky, roly a zdieľané projekty.","languages.name":"Jazyky","languages.line":"Každý text obrazovky v jazykovom súbore, najprv holandčina a flámčina.","ai-tester.name":"AI tester","ai-tester.line":"Tester najprv skontroluje každé odovzdanie a ukáže, čo videl.","website.name":"Web","website.line":"aigile.lol, ukážka a táto časová os.","streaming.name":"Chat a streamovanie","streaming.line":"Discord, Twitch, OBS, režim streamera, GIFy a emoji.","no-ai.name":"Edícia bez AI","no-ai.line":"Tabuľa pre ľudí, ktorí programujú bez AI, a verejné tabule.","night-watch.name":"Nočná hliadka","night-watch.line":"Strážca a Scrum Master držia tímy pri práci, kým spíš.","p-more.name":"Všetko ostatné","p-more.line":"Menšie nápady, ktoré čakajú na rad.","p-android.name":"Telefón a Android","p-android.line":"Tabuľa z telefónu a potom natívna aplikácia pre Android.","p-release.name":"Alfa a ďalej","p-release.line":"Uzavretá alfa, živý web a potom beta.","p-languages.name":"Viac jazykov","p-languages.line":"130 jazykov a režim ponorenia pre tých, čo sa jazyk učia.","p-engines.name":"Viac AI motorov","p-engines.line":"Pre každého agenta si vyber Claude, Codex, Gemini, Copilot alebo Cursor.","p-pro.name":"Profesionálna prax","p-pro.line":"Štítky rizika, brány zlúčenia, karty incidentov a zábradlia.","p-self.name":"Starostlivosť o teba","p-self.line":"Režim únavy, pripomienky starostlivosti o seba a 4:20.","p-servers.name":"Servery a rast","p-servers.line":"Globálne nastavenia servera, roly a plánovanie rastu.","p-livestream.name":"Streamovacie doplnky","p-livestream.line":"Twitch chat, vlastné emoji a verejný živý pohľad."},"words":{"button":"📖 Odborné výrazy","h":"📖 Vysvetlené slová","intro":"Bezplatné vzdelávanie jednoduchým jazykom: pojmy od prvého nápadu po spoľahlivú službu vrátane agilnej práce, tvorby, bezpečnosti a spolupráce s AI.","search":"Hľadať slovo…","none":"Také slovo sa nenašlo.","close":"Zavrieť","count":{"one":"{count} slovo","other":"{count} slov"},"groups":[{"id":"idea","name":"💡 Nápad a prieskum"},{"id":"plan","name":"🗺️ Plánovanie práce"},{"id":"agile","name":"🔁 Agilné spôsoby práce"},{"id":"build","name":"🛠️ Ako to postaviť"},{"id":"test","name":"🧪 Testovanie a kvalita"},{"id":"change","name":"🔀 Bezpečné zmeny"},{"id":"run","name":"🛎️ Prevádzka služby"},{"id":"sec","name":"🔒 Bezpečnosť a súkromie"},{"id":"ai","name":"🤖 Práca s AI"},{"id":"money","name":"💰 Peniaze a licencie"}],"list":[{"id":"discovery","g":"idea","word":"Úvodný prieskum","text":"Úvodná fáza, v ktorej zisťuješ, aký problém sa oplatí riešiť a pre koho, ešte pred tvorbou.","also":["fáza prieskumu","úvodného prieskumu","discovery phase"]},{"id":"problemstmt","g":"idea","word":"Opis problému","text":"Jedna či dve vety o tom, kto má aký problém a prečo na ňom záleží, aby všetci smerovali k tomu istému.","also":["opisy problémov","opisu problému","problem statements"]},{"id":"user","g":"idea","word":"Používateľ","text":"Človek, ktorý používa to, čo tvoríš. Práca má slúžiť jeho potrebám.","also":["používatelia","používateľa","používateľov","users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Zainteresovaná strana","text":"Každý, koho zaujíma výsledok práce alebo koho ovplyvní, napríklad platca, používateľ či podpora.","also":["zainteresované strany","zainteresovanej strany","stakeholders"]},{"id":"persona","g":"idea","word":"Persóna","text":"Vymyslený, ale realistický človek zastupujúci určitý typ používateľa. Tím sa môže pýtať: „Bolo by to pre Sama jednoduché?“","also":["persóny","persón","personas"]},{"id":"userresearch","g":"idea","word":"Používateľský výskum","text":"Rozhovory so skutočnými ľuďmi a ich pozorovanie, aby sa namiesto hádania zistilo, čo naozaj potrebujú.","also":["rozhovory s používateľmi","user interviews"]},{"id":"journey","g":"idea","word":"Cesta používateľa","text":"Kroky človeka od prvého zoznámenia až po dokončenie úlohy, aj mimo tvojho produktu. Ich zakreslenie ukáže, kde sa zasekáva.","also":["cesty používateľov","cesty používateľa","user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Problémové miesto","text":"Niečo, čo dnes ľudí obťažuje alebo spomaľuje. Dobré produkty takéto prekážky odstraňujú.","also":["problémové miesta","problémového miesta","pain points"]},{"id":"assumption","g":"idea","word":"Predpoklad","text":"Niečo, čomu veríš, ale zatiaľ to nikto neoveril. Zápis predpokladov ukáže, čo treba overiť najskôr.","also":["predpoklady","predpokladu","predpokladov","assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypotéza","text":"Odhad, ktorý chceš overiť, aj s očakávaným výsledkom, napríklad „ľudia sa zaregistrujú, ak je prvý mesiac zadarmo“.","also":["hypotézy","hypotéz","hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"Malý plánovaný pokus, ktorý ukáže, či nápad funguje, skôr než doň veľa vložíš.","also":["experimenty","experimentu","experimentov","experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Overenie konceptu (PoC)","text":"Rýchly hrubý pokus, či nápad vôbec môže fungovať. Po získaní odpovede sa zvyčajne zahodí.","also":["PoC","proof of concept","overenie konceptu"]},{"id":"prototype","g":"idea","word":"Prototyp","text":"Skorý model produktu, často obrázky, na ktoré sa dá klikať. Umožní vyskúšať nápad s ľuďmi pred skutočnou tvorbou.","also":["prototypy","prototypu","prototypov","prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe (kostra obrazovky)","text":"Jednoduchý náčrt obrazovky, ktorý ukazuje rozloženie bez farieb a skutočného obsahu.","also":["wireframy","wireframu","drôtené modely","wireframes"]},{"id":"mockup","g":"idea","word":"Vizuálny návrh","text":"Podrobný obrázok budúcej obrazovky so skutočnými farbami a textom, ale zatiaľ bez funkcií.","also":["vizuálne návrhy","vizuálneho návrhu","mockup","mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Obchodné zdôvodnenie","text":"Dôvody pre projekt: jeho cena, prínosy či úspory a riziká.","also":["obchodné zdôvodnenia","obchodného zdôvodnenia","business cases"]},{"id":"feasibility","g":"idea","word":"Uskutočniteľnosť","text":"Či sa dá niečo naozaj vytvoriť a udržiavať s dostupným časom, peniazmi a schopnosťami."},{"id":"outcome","g":"idea","word":"Výsledný prínos","text":"Zmena, ktorú chceš pre ľudí dosiahnuť, napríklad menej zmeškaných termínov. Je dôležitejšia než množstvo vytvorených vecí.","also":["prínosy","prínosu","výsledný prínos","outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Výstup","text":"Niečo, čo tím vytvorí, napríklad nová obrazovka či správa. Samotné vytvorenie ešte neznamená, že to niekomu pomáha.","also":["výstupy","výstupu","výstupov","outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Ukazovateľ úspechu","text":"Číslo, ktoré ukazuje, či práca splnila účel, napríklad viac dokončených objednávok.","also":["ukazovatele úspechu","ukazovateľa úspechu","success metrics"]},{"id":"kpi","g":"idea","word":"Kľúčový ukazovateľ výkonnosti (KPI)","text":"Dôležité číslo, ktoré sleduješ, aby bolo vidno, či veci idú dobre, napríklad počet registrácií za týždeň.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Ciele a kľúčové výsledky (OKR)","text":"Spôsob určovania cieľov: cieľ hovorí, čo chceš dosiahnuť, a niekoľko kľúčových výsledkov sú čísla, ktoré ukážu, že sa to podarilo.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Produkt","text":"Vec, ktorú tvoríš a udržiavaš pre používateľov, napríklad aplikácia, web či nástroj.","also":["produkty","produktu","produktov","products"],"noTip":1},{"id":"vision","g":"plan","word":"Vízia produktu","text":"Stručné vyjadrenie, komu produkt pomáha a kam dlhodobo smeruje.","also":["vyhlásenie vízie","vízie produktu","vision statement"]},{"id":"po","g":"plan","word":"Vlastník produktu (PO)","text":"Človek, ktorý rozhoduje, čo sa vytvorí a v akom poradí, aby tím riešil to najdôležitejšie. V AI-gile si to ty.","also":["PO","vlastníci produktu","vlastníka produktu","product owners"]},{"id":"pm","g":"plan","word":"Produktový manažér (PM)","text":"Človek zodpovedný za smerovanie produktu: aké problémy rieši, pre koho a prečo. PM môže znamenať aj projektového manažéra, preto si význam over.","also":["produktoví manažéri","produktového manažéra","product managers"]},{"id":"projmgr","g":"plan","word":"Projektový manažér","text":"Človek, ktorý stráži termíny a rozpočet projektu a sleduje, kto čo urobí a dokedy.","also":["projektoví manažéri","projektového manažéra","project managers"]},{"id":"roadmap","g":"plan","word":"Plán rozvoja","text":"Približné poradie práce na najbližšie mesiace. Ukazuje smer, nie presné dátumy, a mení sa s novými poznatkami.","also":["plány rozvoja","plánu rozvoja","roadmapa","roadmaps"]},{"id":"milestone","g":"plan","word":"Míľnik","text":"Významný bod projektu, napríklad „prvá verzia v prevádzke“ alebo „100 používateľov“.","also":["míľniky","míľnika","míľnikov","milestones"]},{"id":"mvp","g":"plan","word":"Minimálny životaschopný produkt (MVP)","text":"Najmenšia verzia produktu, ktorá je už užitočná skutočným ľuďom, aby sa od nich dalo čo najskôr učiť.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Požiadavka","text":"Niečo, čo hotový produkt musí robiť alebo spĺňať.","also":["požiadavky","požiadaviek","requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Rozsah","text":"Čo práca zahŕňa a rovnako dôležité je aj to, čo nezahŕňa.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Nekontrolovaný rast rozsahu","text":"Keď do práce postupne pribúdajú ďalšie veci bez dohody o čase či cene navyše, takže sa stále nekončí.","also":["rozširovanie funkcií","feature creep"]},{"id":"feature","g":"plan","word":"Funkcia","text":"Jedna vec, ktorú produkt dokáže pre ľudí urobiť, napríklad obnoviť heslo.","also":["funkcie","funkcií","features"],"noTip":1},{"id":"epic","g":"plan","word":"Epik","text":"Veľký celok práce, ktorý sa nedá zvládnuť naraz, preto sa delí na menšie karty.","also":["epiky","epiku","epikov","epics"]},{"id":"story","g":"plan","word":"Používateľský príbeh","text":"Malá úloha opísaná očami používateľa: „Ako zákazník si chcem uložiť košík, aby som mohol pokračovať neskôr.“ Otvára rozhovor o tom, čo vytvoriť.","also":["používateľské príbehy","používateľského príbehu","user story","user stories"]},{"id":"ac","g":"plan","word":"Akceptačné kritériá (AC)","text":"Vopred dohodnuté kontroly, ktoré musí karta splniť, aby sa považovala za hotovú, napríklad „košík tam zostane aj po odhlásení a opätovnom prihlásení“.","also":["akceptačné kritériá","acceptance criteria"]},{"id":"task","g":"plan","word":"Úloha","text":"Jedna práca na vykonanie, často malý krok väčšieho príbehu.","also":["úlohy","úloh","tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Tiket","text":"Iný názov karty: úloha alebo požiadavka sledovaná od začiatku do konca.","also":["tikety","tiketu","tiketov","tickets"]},{"id":"priority","g":"plan","word":"Priorita","text":"Dôležitosť či naliehavosť oproti ostatným veciam, aby sa najdôležitejšie riešilo najskôr.","also":["priority","priorít","priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Určovanie priorít","text":"Zoradenie práce podľa dôležitosti. Metóda MoSCoW rozlišuje: nevyhnutné, žiaduce, možné a tentoraz vynechané.","also":["určiť priority","MoSCoW"]},{"id":"estimate","g":"plan","word":"Odhad","text":"Najlepší odhad veľkosti či trvania práce. Je to odhad, nie sľub.","also":["odhady","odhadu","odhadov","odhadovanie","estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Body príbehu","text":"Odhad veľkosti práce porovnávaním kariet medzi sebou („asi dvakrát väčšia než tamtá“), nie v hodinách. Neslúžia na porovnávanie tímov.","also":["bod príbehu","bodov príbehu","story point"]},{"id":"tshirt","g":"plan","word":"Odhad veľkosťami tričiek","text":"Odhad veľkosti práce ako S, M, L či XL. Rýchly a postačujúci pre úvodné plánovanie.","also":["veľkosti tričiek","t-shirt sizes"]},{"id":"poker","g":"plan","word":"Plánovací poker","text":"Hra na odhadovanie: všetci naraz ukážu kartu s veľkosťou a potom autori najvyššieho a najnižšieho odhadu vysvetlia prečo.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Závislosť","text":"Keď sa práca nemôže začať alebo skončiť, kým sa nedokončí iná.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Prekážka","text":"Čokoľvek, čo práve bráni práci pokračovať, napríklad chýbajúca odpoveď či pokazený nástroj.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Termín dokončenia","text":"Dátum, do ktorého musí byť niečo hotové.","also":["termíny","termínu","dokedy","deadline","deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Odovzdávaný výstup","text":"Konkrétny výsledok práce, ktorý sa odovzdáva, napríklad funkčná stránka alebo správa.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Prognóza","text":"Predpoveď pravdepodobného vývoja, napríklad dokončenia práce, podľa doterajších poznatkov.","also":["prognózy","prognóz","forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metrika","text":"Čokoľvek, čo meriaš a sleduješ v čase, napríklad návštevy stránky či čas opravy.","also":["metriky","metrík","metrics"]},{"id":"feedback","g":"plan","word":"Spätná väzba","text":"Čo ti ľudia hovoria o tvojej práci, dobré aj zlé. Včasná a častá spätná väzba je základ agilnej práce.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Čakací zoznam nápadov a zatiaľ nenaplánovanej práce, najdôležitejšie navrchu. Na ničom z neho sa nepracuje, kým sa karta nepresunie do stĺpca Na urobenie."},{"id":"sprint","g":"agile","word":"Sprint","text":"Krátke pevne určené obdobie práce, často týždeň či dva, najviac mesiac, s cieľom a dohodnutými kartami na dokončenie.","also":["sprinty","sprintov","sprintu"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Krátke denné stretnutie: čo každý urobil, čo urobí ďalej a čo mu bráni. V Scrume sa nazýva denný scrum.","also":["standup","stand-upy","stand-upu","stand-ups","daily scrum","daily stand-up","denné stretnutie","denný scrum"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Spôsob práce, pri ktorom karty prechádzajú stĺpcami nástenky, napríklad Na urobenie, Rozrobené a Hotovo. Tím obmedzuje množstvo súbežnej práce, aby práca plynulo pokračovala."},{"id":"wip","g":"agile","word":"WIP limit","text":"WIP znamená rozpracovanú prácu. Limit WIP určuje najväčší počet kariet v stĺpci naraz, aby tím dokončil začaté veci skôr, než začne ďalšie.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definícia Hotovo","text":"Krátky kontrolný zoznam tímu, čo znamená „hotové“, napríklad otestované a vysvetlené, predtým než ti karta príde. Jej dvojča, Definícia Pripravené, hovorí, kedy je karta dosť jasná na začatie.","also":["Definition of Ready","DoD","DoR","Definícia Pripravené","Definition of Done"]},{"id":"retro","g":"agile","word":"Retro","text":"Pravidelné obzretie sa za tým, ako tím pracuje, s dohodou na jednej či dvoch veciach, ktoré nabudúce robiť lepšie. Retro je skratka slova retrospektíva. V AI-gile retro navrhne zmenu v spôsobe práce tímu a ty povieš Do toho alebo Zatiaľ nie.","also":["retrá","retrospektíva","retrospektívy"]},{"id":"swarm","g":"agile","word":"Roj","text":"Všetci odložia inú prácu a spoločne riešia jednu naliehavú vec až do dokončenia. V AI-gile pomáhajú všetky tímy jednému projektu a ostatné zatiaľ čakajú.","also":["swarm","swarming","rojenie"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"V Scrume človek, ktorý pomáha tímu dobre pracovať: odstraňuje prekážky, drží stretnutia v správnych koľajach a učí dobré návyky bez rozkazovania. V AI-gile Lead Scrum Master naprieč všetkými projektmi sleduje zaseknuté karty, postrčí tímy a pripomenie ti, čo čaká.","also":["Lead Scrum Master","hlavný Scrum Master"]},{"id":"agile","g":"agile","word":"Agile (agilný prístup)","text":"Práca po malých krokoch: trochu vytvoríš, často ukážeš výsledok, učíš sa z reakcií a priebežne meníš plán.","also":["agilný vývoj","Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agilný manifest","text":"Krátke vyhlásenie tvorcov softvéru z roku 2001. Uprednostňuje ľudí, funkčné výsledky, spoluprácu so zákazníkmi a reakcie na zmeny pred zložitými plánmi a papierovaním.","also":["Manifest agilného vývoja softvéru","Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Vodopádový model","text":"Starší spôsob: najprv všetko naplánovať, potom vytvoriť a napokon otestovať. Neskoré zmeny sú ťažké a drahé.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iterácia","text":"Jedno kolo tvorby, kontroly a zlepšovania. Agilná práca pozostáva z takýchto kôl; sprint je jedným druhom.","also":["iterácie","iterácií","iterations"]},{"id":"increment","g":"agile","word":"Prírastok","text":"Nová funkčná časť produktu pridaná počas sprintu alebo kola práce, ktorá zapadá do existujúceho celku.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"Obľúbený agilný spôsob: malý tím pracuje v krátkych sprintoch k cieľu, s určenými rolami a pravidelnými stretnutiami na plánovanie, kontrolu a zlepšovanie."},{"id":"scrumteam","g":"agile","word":"Scrum tím","text":"Malá skupina vykonávajúca prácu v Scrume: vlastník produktu, Scrum Master a vývojári.","also":["Scrum tímy","Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Udalosti Scrumu","text":"Pravidelné stretnutia Scrumu: plánovanie sprintu, denný scrum, prehliadka sprintu a retro. Mnohí ich nazývajú ceremónie.","also":["ceremónie","ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Plánovanie sprintu","text":"Úvodné stretnutie sprintu, kde sa tím dohodne na jeho zmysle, kartách a začiatku práce.","also":["plánovacie stretnutie","planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Cieľ sprintu","text":"Jedna veta o účele sprintu. Menšie úlohy sa môžu meniť, ak sa cieľ splní.","also":["ciele sprintu","cieľa sprintu","sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Zoznam práce sprintu","text":"Karty vybrané do aktuálneho sprintu a plán tímu na ich dokončenie.","also":["sprint backlog","sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Zoznam práce produktu","text":"Úplný zoradený zoznam možnej práce na produkte, najdôležitejšie navrchu. Mení sa s novými poznatkami.","also":["product backlog","product backlogs"]},{"id":"productgoal","g":"agile","word":"Cieľ produktu","text":"Väčší výsledok, ku ktorému produkt smeruje a ktorý pomáha vybrať ďalšiu prácu.","also":["ciele produktu","product goals"]},{"id":"refinement","g":"agile","word":"Spresňovanie zoznamu práce","text":"Pravidelné upratovanie, delenie, zoraďovanie a dopĺňanie kariet v zozname práce, aby sa dali prevziať. Nazýva sa aj backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Prehliadka sprintu","text":"Záverečné stretnutie sprintu, kde tím ukáže hotovú prácu a vypočuje si reakcie pre ďalšie rozhodovanie.","also":["prehliadky sprintu","sprint reviews"]},{"id":"demo","g":"agile","word":"Ukážka","text":"Živé predvedenie hotovej fungujúcej práce ľuďom, ktorí ju žiadali.","also":["ukážky","ukážok","demo","demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Časový rámec","text":"Pevne určený čas na činnosť. Po jeho uplynutí skončíš, aj keď nie je všetko hotové.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Rýchlosť tímu","text":"Koľko práce tím zvyčajne dokončí za sprint; podľa toho plánuje, koľko si vezme nabudúce. Nie je to hodnotenie, ako tvrdo ľudia pracujú.","also":["rýchlosť tímu","team velocity"]},{"id":"capacity","g":"agile","word":"Kapacita","text":"Koľko práce tím zvládne za obdobie po zohľadnení dovoleniek a iných povinností.","noTip":1},{"id":"burndown","g":"agile","word":"Graf zostávajúcej práce","text":"Graf, v ktorom zostávajúca práca sprintu deň po dni klesá. Vodorovná čiara znamená, že sa niečo zaseklo.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Graf dokončenej práce","text":"Graf rastúceho množstva hotovej práce vedľa celkového plánu ukazuje, kedy môžeš dosiahnuť cieľ.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanbanová nástenka","text":"Samotná nástenka: stĺpec pre každú fázu práce a karty prechádzajúce medzi nimi.","also":["kanbanové nástenky","kanbanovej nástenky","Kanban boards"]},{"id":"pullsys","g":"agile","word":"Ťahový systém","text":"Nová práca sa začína až vtedy, keď má niekto priestor ju prevziať, namiesto pridávania už preťaženým ľuďom.","also":["ťahový systém","pull-based"]},{"id":"flow","g":"agile","word":"Tok práce","text":"Ako plynulo práca prechádza nástenkou. Pri dobrom toku sa karty hýbu a nehromadia.","also":["tok práce","flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Dodacia lehota","text":"Čas od požiadavky až po jej dokončenie.","also":["dodacie lehoty","lead times"]},{"id":"cycletime","g":"agile","word":"Čas cyklu","text":"Čas od skutočného začiatku práce na karte až po dokončenie.","also":["časy cyklu","cycle times"]},{"id":"throughput","g":"agile","word":"Priepustnosť","text":"Počet kariet dokončených za týždeň alebo iné určené obdobie.","also":["priepustnosť","throughput rate"]},{"id":"bottleneck","g":"agile","word":"Úzke miesto","text":"Fáza, kde sa práca hromadí a spomaľuje všetko za sebou, podobne ako úzke hrdlo fľaše.","also":["úzke miesta","úzkeho miesta","bottlenecks"]},{"id":"swimlane","g":"agile","word":"Dráha","text":"Vodorovný pás nástenky združujúci určitý druh kariet, napríklad naliehavé úlohy alebo karty jedného tímu.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean (štíhly prístup)","text":"Spôsob práce odstraňujúci plytvanie, teda všetko bez prínosu pre zákazníka, a udržiavajúci plynulý tok práce."},{"id":"waste","g":"agile","word":"Plytvanie","text":"V prístupe Lean je to námaha bez prínosu zákazníkovi, napríklad čakanie, prerábanie či tvorba nepoužívaných vecí.","noTip":1},{"id":"kaizen","g":"agile","word":"Neustále zlepšovanie","text":"Pravidelné malé zmeny a overovanie, či pomohli. Jednou cestou sú retrospektívy; nazýva sa aj kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Samoorganizujúci sa tím","text":"Tím, ktorý sám rozhoduje, ako vykoná prácu, namiesto pokynov na každý krok.","also":["samoorganizácia","self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Medzifunkčný tím","text":"Tím so všetkými schopnosťami potrebnými na dokončenie práce, napríklad návrh, tvorba a testovanie.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Prieskumná úloha","text":"Krátky časovo ohraničený prieskum, ktorý zodpovie otázku pred začatím skutočnej práce.","also":["prieskumné úlohy","prieskumnej úlohy","spikes"]},{"id":"rework","g":"agile","word":"Prerábanie","text":"Opakovanie práce, pretože na prvýkrát nebola správna.","also":["reworked"]},{"id":"safe","g":"agile","word":"Agile vo veľkom (SAFe)","text":"Spôsoby uplatnenia agilnej práce vo veľkej organizácii s mnohými tímami. Známym príkladom je rámec SAFe.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Priečinok kódu projektu s úplnou históriou uložených zmien. Môže byť na počítači, GitHube alebo na oboch.","also":["repozitár","repozitára"]},{"id":"branch","g":"build","word":"Branch","text":"Samostatná línia práce v kóde, aby sa dali robiť zmeny bez dotyku hlavnej verzie.","also":["branche","vetva","vetvy"]},{"id":"commit","g":"build","word":"Commit","text":"Uložený snímok kódu s krátkou poznámkou o tom, čo sa zmenilo. Vždy sa k nemu dá vrátiť.","also":["commity","commitu","commitov"]},{"id":"push","g":"build","word":"Push","text":"Odoslanie uložených snímok (commitov) z počítača do spoločnej online kópie, napríklad na GitHub, na zálohovanie a sprístupnenie ostatným."},{"id":"merge","g":"build","word":"Merge","text":"Spojenie zmien jednej vetvy do druhej, zvyčajne späť do hlavnej verzie."},{"id":"pr","g":"build","word":"Pull request","text":"Žiadosť o kontrolu zmien vetvy a ich zlúčenie do hlavnej verzie. Niektoré weby ju nazývajú merge request.","also":["PR","PRs","merge request","žiadosť o zlúčenie"]},{"id":"refactor","g":"build","word":"Refaktoring","text":"Upratovanie kódu bez zmeny toho, čo robí: menšie súbory, jasnejšie názvy, menej opakovania."},{"id":"bug","g":"build","word":"Bug","text":"Niečo, čo nefunguje tak, ako má.","also":["bugy","bugu"]},{"id":"peerreview","g":"build","word":"Kontrola kolegami","text":"Ďalší pár očí: prácu pred tebou skontroluje niekto iný než autor, aby sa zachytilo viac chýb. V AI-gile každú kartu kontroluje iná AI.","also":["peer review","code review","revízia kódu"]},{"id":"code","g":"build","word":"Kód","text":"Napísané pokyny, ktoré počítaču hovoria, čo robiť. Nazývajú sa aj zdrojový kód.","also":["kódu","zdrojový kód","zdrojového kódu","source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programovací jazyk","text":"Jazyk na písanie kódu, napríklad JavaScript, Python či Java. Každý sa hodí na iné úlohy.","also":["programovacie jazyky","programovacieho jazyka","programming languages"]},{"id":"developer","g":"build","word":"Vývojár (dev)","text":"Človek, ktorý píše a mení kód. Nazýva sa aj programátor či softvérový inžinier.","also":["vývojár","vývojári","vývojára","vývojárov","programátor","programátori","programátora","developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Softvér","text":"Programy bežiace na počítačoch a telefónoch, na rozdiel od samotných zariadení, teda hardvéru.","noTip":1},{"id":"app","g":"build","word":"Aplikácia","text":"Program, pomocou ktorého ľudia niečo vykonávajú na telefóne, počítači či vo webovom prehliadači.","also":["aplikácie","aplikácií","appka","apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Webová aplikácia","text":"Aplikácia bežiaca vo webovom prehliadači, takže netreba nič inštalovať.","also":["webové aplikácie","webovej aplikácie","web apps","web application"]},{"id":"frontend","g":"build","word":"Frontend","text":"Časť aplikácie, ktorú vidíš a na ktorú klikáš: obrazovky, tlačidlá a texty, často v prehliadači.","also":["používateľská časť","front-end","frontend"]},{"id":"backend","g":"build","word":"Backend","text":"Časť aplikácie na pozadí, ktorá uchováva údaje a vykonáva prácu po kliknutí, napríklad overí heslo.","also":["serverová časť","back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Práca na používateľskej časti aj na časti na pozadí.","also":["full-stack"]},{"id":"ui","g":"build","word":"Používateľské rozhranie (UI)","text":"Čo človek vidí a používa na obrazovke: rozloženie, tlačidlá, ponuky a texty.","also":["UI","používateľské rozhranie","user interface"]},{"id":"ux","g":"build","word":"Používateľská skúsenosť (UX)","text":"Aké je niečo používať: jednoduché, jasné a príjemné, alebo mätúce a pomalé.","also":["UX","používateľská skúsenosť","user experience"]},{"id":"accessibility","g":"build","word":"Prístupnosť (a11y)","text":"Tvorba vecí použiteľných pre všetkých, aj pre ľudí so slabým zrakom, bez myši či s čítačkou obrazovky.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responzívny dizajn","text":"Prispôsobenie stránok každej veľkosti obrazovky od telefónu po veľký monitor.","also":["responzívny"]},{"id":"designsys","g":"build","word":"Dizajnový systém","text":"Spoločná súprava farieb, písiem, tlačidiel a pravidiel, aby obrazovky vyzerali a fungovali jednotne.","also":["dizajnové systémy","dizajnového systému","design systems"]},{"id":"architecture","g":"build","word":"Architektúra","text":"Celkové usporiadanie systému: hlavné časti a spôsob ich vzájomnej komunikácie."},{"id":"database","g":"build","word":"Databáza (DB)","text":"Usporiadané úložisko informácií, podobné výkonnej tabuľke, ktorú aplikácia môže čítať a meniť.","also":["databáza","databázy","databáz","database","databases","DB"]},{"id":"schema","g":"build","word":"Schéma databázy","text":"Usporiadanie databázy: aké tabuľky obsahuje a čo patrí do každej z nich.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Jazyk na získavanie a zmenu údajov v mnohých databázach. Skratka znamená štruktúrovaný dopytovací jazyk.","also":["Structured Query Language","štruktúrovaný dopytovací jazyk"]},{"id":"data","g":"build","word":"Údaje","text":"Informácie uložené v počítači, napríklad mená, objednávky či nastavenia.","also":["údajov","dáta","súbor údajov","dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"Stále zapnutý počítač odpovedajúci na požiadavky iných počítačov, napríklad odoslaním webovej stránky.","also":["servery","servera","serverov","servers"]},{"id":"client","g":"build","word":"Klient","text":"Strana, ktorá o niečo žiada server, zvyčajne prehliadač či aplikácia. V obchode klient znamená aj zákazníka.","also":["klienti","klienta","klientov","clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Dohodnutá ponuka požiadaviek medzi programami, napríklad žiadosť meteorologickej službe o dnešnú predpoveď.","also":["APIs","application programming interface","aplikačné programové rozhranie"]},{"id":"endpoint","g":"build","word":"Koncový bod","text":"Jedna položka ponuky API: webová adresa, cez ktorú program získava alebo posiela údaje.","also":["koncové body","koncového bodu","endpoints"]},{"id":"integration","g":"build","word":"Integrácia","text":"Prepojenie dvoch systémov, aby spolupracovali, napríklad odosielanie objednávok z obchodu do účtovníctva.","also":["integrácie","integrácií","integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"Správa, ktorú systém automaticky pošle inému hneď po udalosti, napríklad „platba prijatá“.","also":["webhooky","webhooku","webhooks"]},{"id":"library","g":"build","word":"Knižnica","text":"Hotový kód od niekoho iného, ktorý môžeš použiť namiesto vlastného písania.","also":["knižnice","knižníc","libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"Pripravená konštrukcia aplikácie, ktorá určuje veľkú časť usporiadania kódu, podobne ako kostra domu.","also":["frameworky","frameworku","frameworks"]},{"id":"sdk","g":"build","word":"Súprava na vývoj softvéru (SDK)","text":"Súprava nástrojov, kódu a príkladov na tvorbu softvéru pre konkrétnu platformu či službu.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Softvérová závislosť","text":"Knižnica či nástroj potrebný na fungovanie kódu. Aktualizácie sú dôležité pre bezpečnosť.","also":["softvérové závislosti","software dependencies"]},{"id":"package","g":"build","word":"Balík","text":"Balík hotového kódu, ktorý môžeš nainštalovať a používať v projekte.","also":["balíky","balíka","balíkov","balíček","packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Správca balíkov","text":"Nástroj na sťahovanie a aktualizáciu balíkov potrebných pre kód. Bežným príkladom je npm.","also":["správcovia balíkov","správcu balíkov","package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"Najrozšírenejší nástroj na uchovávanie histórie zmien kódu pomocou uložených snímok a vetiev."},{"id":"github","g":"build","word":"GitHub","text":"Web, ktorý uchováva repozitáre Gitu online, aby tímy mohli zdieľať kód, kontrolovať zmeny a sledovať prácu."},{"id":"vcs","g":"build","word":"Správa verzií","text":"Úplná história zmien súborov umožňujúca zistiť, kto čo zmenil, a vrátiť sa späť. Toto robí Git.","also":["správy verzií","verziovanie","source control","version control system"]},{"id":"clone","g":"build","word":"Klonovanie","text":"Vytvorenie úplnej vlastnej kópie repozitára aj s históriou na počítači.","also":["klonovaný","klonovanie","cloned","cloning"]},{"id":"pull","g":"build","word":"Pull (stiahnutie)","text":"Stiahnutie najnovších commitov zo spoločnej kópie, napríklad z GitHubu, do tvojho počítača. Opak príkazu push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Hlavná vetva","text":"Oficiálna verzia kódu, z ktorej všetci vychádzajú, často nazvaná main alebo master.","also":["hlavnej vetvy","main","master branch"]},{"id":"conflict","g":"build","word":"Konflikt pri zlúčení","text":"Dve zmeny upravili tie isté riadky rozdielne, takže ich počítač nevie spojiť a človek musí rozhodnúť.","also":["konflikty zlúčenia","merge conflicts"]},{"id":"diff","g":"build","word":"Diff (rozdiely)","text":"Zobrazenie presných rozdielov medzi verziami: pridané a odstránené riadky.","also":["diffy","diffs"]},{"id":"fork","g":"build","word":"Fork (vlastná kópia)","text":"Vlastná kópia cudzieho repozitára, ktorú môžeš meniť bez zásahu do pôvodného.","also":["forky","forku","forks","forked"]},{"id":"script","g":"build","word":"Skript","text":"Krátky program vykonávajúci úlohu automaticky, napríklad upratanie súborov či spustenie aplikácie.","also":["skripty","skriptu","skriptov","scripts"],"noTip":1},{"id":"build","g":"build","word":"Zostavenie","text":"Premena kódu na podobu pripravenú na spustenie alebo samotný výsledok tejto premeny.","also":["zostavenia","build","buildy","builds"],"noTip":1},{"id":"compile","g":"build","word":"Kompilácia","text":"Preklad ľuďmi napísaného kódu do podoby, ktorú počítač vie priamo spustiť.","also":["kompilátor","kompilovať","compiler"]},{"id":"cli","g":"build","word":"Príkazový riadok (CLI)","text":"Textové okno, do ktorého píšeš pokyny pre počítač namiesto klikania. Nazýva sa aj terminál.","also":["príkazový riadok","command line","command-line","CLI","terminál"]},{"id":"config","g":"build","word":"Konfigurácia","text":"Nastavenia riadiace správanie softvéru, uložené oddelene od kódu pre jednoduchú zmenu.","also":["nastavenia","config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Premenná prostredia","text":"Nastavenie odovzdané programu pri spustení, často adresa či heslo, aby neboli priamo v kóde.","also":["premenné prostredia","premennej prostredia","environment variables","env var"]},{"id":"debugging","g":"build","word":"Ladenie","text":"Hľadanie príčiny nefunkčnosti a jej oprava.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Párové programovanie","text":"Dvaja ľudia, prípadne človek a AI, pracujú na rovnakom kóde: jeden píše a druhý kontroluje.","also":["pairing"]},{"id":"docs","g":"build","word":"Dokumentácia","text":"Písomné vysvetlenia fungovania alebo používania niečoho.","also":["dokumentácia","documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"Prvý súbor na prečítanie v repozitári: čo projekt robí a ako ho spustiť.","also":["súbory README","READMEs"]},{"id":"legacy","g":"build","word":"Starší systém","text":"Starší stále používaný systém, ktorý sa ťažko mení, často preto, že mu už málokto rozumie.","also":["staršie systémy","legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technický dlh","text":"Zjednodušenia, ktoré šetria čas dnes, no spomaľujú budúce zmeny, podobne ako úročená pôžička. Úprava štruktúry kódu tento dlh znižuje.","also":["technického dlhu","tech debt"]},{"id":"test","g":"test","word":"Test","text":"Overenie, či niečo funguje tak, ako má. Niektoré testy spúšťa počítač sám pri každej zmene kódu; pri iných ty skúšaš hotovú kartu, kým ju prijmeš.","also":["testy","testu","testovanie","testovať"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Skratka pre zabezpečenie kvality: všetko na overenie práce pred nasadením. V AI-gile ide o automatické kontroly; červené QA znamená zlyhanie, ktoré treba pred nasadením opraviť.","also":["kontrola kvality","kontroly kvality","zabezpečenie kvality"]},{"id":"testpile","g":"test","word":"Balík testov","text":"Hotové karty, ktoré čakajú, kým ich vyskúšaš, jedna po druhej. Jednu prijmi alebo ju pošli späť s poznámkou a príde ďalšia.","also":["balíky testov","testovací balík"]},{"id":"autotest","g":"test","word":"Automatizovaný test","text":"Kontrola, ktorú počítač sám spustí pri každej zmene kódu, aby chyby zachytil včas.","also":["automatizované testy","automatizovaného testu","automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Ručný test","text":"Človek ručne skúša výsledok práce, aby zistil, či sa správa správne.","also":["ručné testy","ručné testovanie","manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Jednotkový test","text":"Malá automatická kontrola jednej drobnej časti kódu samostatne.","also":["jednotkové testy","jednotkového testu","unit tests"]},{"id":"integtest","g":"test","word":"Integračný test","text":"Kontrola, či viaceré časti správne fungujú spolu, nielen každá zvlášť.","also":["integračné testy","integračného testu","integration tests"]},{"id":"endtoend","g":"test","word":"Test od začiatku do konca (E2E)","text":"Test napodobňujúci skutočného používateľa od začiatku do konca, napríklad registráciu, nákup a platbu.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"Používateľské akceptačné testovanie (UAT)","text":"Ľudia, ktorí prácu zadali, ju sami vyskúšajú a potvrdia, či spĺňa ich potreby. V AI-gile na to slúži kôpka na testovanie.","also":["UAT","acceptance testing","akceptačné testovanie"]},{"id":"regression","g":"test","word":"Regresia","text":"Niečo, čo fungovalo, sa po zmene pokazilo. Regresné testy overujú, že pôvodné funkcie stále fungujú.","also":["regresie","regresný test","regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Základný overovací test","text":"Veľmi rýchla kontrola hlavných funkcií, napríklad hneď po nasadení. Ak zlyhá, zastav sa a preskúmaj príčinu.","also":["základné overovacie testy","smoke tests"]},{"id":"exploratory","g":"test","word":"Prieskumné testovanie","text":"Voľné skúšanie produktu rôznymi spôsobmi, aby sa našli problémy, ktoré plánované kontroly prehliadnu.","also":["prieskumný test","exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Testovací prípad","text":"Jeden zapísaný scenár na vyskúšanie: kroky a očakávaný výsledok.","also":["testovacie prípady","testovacieho prípadu","test cases"]},{"id":"coverage","g":"test","word":"Pokrytie testami","text":"Koľko kódu overujú automatické testy. Väčšie pokrytie zvyčajne pomáha, no samo osebe nedokazuje správne fungovanie.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Testovacie údaje","text":"Vymyslené vzorové údaje na testovanie, aby sa neodhalili súkromné údaje skutočných ľudí.","also":["testovacie dáta","test fixtures"]},{"id":"edgecase","g":"test","word":"Hraničný prípad","text":"Nezvyčajná situácia na hranici možností, napríklad prázdny formulár či meno s apostrofom, kde často vznikajú chyby.","also":["hraničné prípady","hraničného prípadu","edge cases"]},{"id":"happypath","g":"test","word":"Ideálny priebeh","text":"Bežná cesta, pri ktorej ide všetko správne. Dobré testovanie skúša aj problémové cesty."},{"id":"perftest","g":"test","word":"Výkonnostné testovanie","text":"Overovanie rýchlosti a zvládania náročných podmienok.","also":["výkonnostný test","performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Záťažové testovanie","text":"Overovanie, ako systém zvláda veľa používateľov naraz.","also":["záťažový test","load test","load tests"]},{"id":"sectest","g":"test","word":"Bezpečnostné testovanie","text":"Hľadanie slabín umožňujúcich zneužitie systému alebo prístup k neprístupným údajom.","also":["bezpečnostný test","security test","security tests"]},{"id":"accesstest","g":"test","word":"Testovanie prístupnosti","text":"Overovanie použiteľnosti pre ľudí s rôznymi schopnosťami, aj s čítačkou obrazovky či iba klávesnicou.","also":["test prístupnosti","accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"Automatická kontrola pravdepodobných chýb a neprehľadného štýlu kódu, podobná kontrole pravopisu.","also":["linter","lint"]},{"id":"static","g":"test","word":"Statická analýza","text":"Automatické čítanie kódu na hľadanie problémov bez jeho spustenia.","also":["statická analýza kódu","static code analysis"]},{"id":"flaky","g":"test","word":"Nestabilný test","text":"Test, ktorý bez jasnej príčiny raz prejde a inokedy zlyhá, preto mu nemožno úplne veriť.","also":["nestabilné testy","nestabilného testu","flaky tests"]},{"id":"repro","g":"test","word":"Zopakovanie chyby","text":"Zámerné opätovné vyvolanie chyby rovnakými krokmi, aby sa dala preskúmať a opraviť. Zápis krokov je najcennejšou časťou hlásenia chyby.","also":["reprodukcia","repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Závažnosť","text":"Aký vážny dosah má problém, od drobnej nepríjemnosti po úplné zastavenie.","also":["stupeň závažnosti","severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Skopírovanie novej verzie softvéru na počítače, ktoré ju prevádzkujú, napríklad do testovacej alebo ostrej prevádzky."},{"id":"release","g":"change","word":"Vydanie","text":"Pomenovaný balík hotovej práce, ktorý ide naživo naraz, s krátkymi poznámkami o tom, čo sa zmenilo. 🚀 Vydania napíšu poznámky z hotových kariet.","also":["vydania","release","releasy"]},{"id":"rollback","g":"change","word":"Vrátiť späť","text":"Návrat k poslednej funkčnej verzii, keď nová spôsobuje problémy. V AI-gile funkcia Vrátiť späť spojí kroky na zrušenie jednotlivých zmien do jedného kontrolného zoznamu.","also":["rollback","vrátenie späť","vrátené späť"]},{"id":"live","g":"change","word":"Naživo","text":"Skutočná verzia, ktorú ľudia používajú, na rozdiel od kópie na skúšanie. Vývojári tomu hovoria aj produkcia.","also":["produkcia","ostrá prevádzka","live"],"noTip":1},{"id":"change","g":"change","word":"Zmena","text":"Plánovaná zmena niečoho, na čo sa ľudia spoliehajú, najprv zapísaná: čo, prečo, riziko, kedy a ako ju vrátiť. Začni ju cez 🔀 Zadať zmenu.","also":["zmeny","žiadosť o zmenu","žiadosti o zmenu"],"noTip":1},{"id":"risk","g":"change","word":"Riziko","text":"Niečo, čo by sa mohlo pokaziť, ohodnotené podľa toho, aké je to pravdepodobné a aké zlé by to bolo. ⚠️ Riziká ich držia v jednom zozname, najvyššie skóre navrchu, každé s dátumom, kedy sa naň znova pozrieť.","also":["riziká","register rizík"]},{"id":"chgwin","g":"change","word":"Okno zmien","text":"Časy, kedy môžu zmeny ísť naživo, napríklad pokojný utorkový večer. Mimo okna sa karta zmeny nedá dokončiť, pokiaľ nejde o niečo naliehavé.","also":["okná zmien","change window"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Záverečná kontrola tesne pred nasadením: každý schvaľovateľ povie Go alebo No go. Pokračuje sa iba vtedy, keď všetci povedia Go.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Schválenie","text":"Čakanie na áno, kým sa práca začne. Karta, ktorú zadá priateľ, alebo zmena čaká v ✅ Schváleniach, kým ju neschváliš alebo neodmietneš.","also":["schválenia","schváliť"]},{"id":"quiettime","g":"change","word":"Tichý čas","text":"Obdobie, napríklad počas živého vysielania, ukážky alebo cez noc, keď sa nič nenasadzuje. Tímy ďalej pracujú a testujú, ale nasadenie počká do jeho konca. Inde sa to nazýva zmrazenie zmien.","also":["tiché časy","zmrazenie zmien","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"Tvorcovia a prevádzkovatelia softvéru pracujú ako jeden tím s množstvom automatizácie, aby zmeny prichádzali často a bezpečne."},{"id":"cicd","g":"change","word":"CI/CD (priebežná integrácia a dodávanie)","text":"Zmeny všetkých sa často spájajú do hlavnej verzie a zakaždým sa automaticky overia (priebežná integrácia), takže softvér je vždy pripravený na nasadenie jedným tlačidlom (priebežné dodávanie).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Priebežné nasadzovanie","text":"Krok za priebežným dodávaním: každá overená zmena sa automaticky nasadí bez stlačenia tlačidla.","also":["priebežné nasadzovanie","continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline (postup spracovania)","text":"Automatický sled krokov zmeny cestou do prevádzky, napríklad zostavenie, testovanie a nasadenie.","also":["postupy spracovania","pipelines"]},{"id":"environment","g":"change","word":"Prostredie","text":"Samostatná kópia systému na určitý účel, napríklad vývoj, testovanie alebo ostrú prevádzku.","also":["prostredia","prostredí","environments"],"noTip":1},{"id":"devenv","g":"change","word":"Vývojové prostredie","text":"Kópia pre vývojára, často na jeho počítači, kde prípadné poruchy nikomu neublížia.","also":["vývojové prostredie","dev environment"]},{"id":"testenv","g":"change","word":"Testovacie prostredie","text":"Samostatná kópia systému iba na testovanie, aby skutočná služba zostala nedotknutá.","also":["testovacie prostredia","test environments"]},{"id":"staging","g":"change","word":"Predprodukčné prostredie","text":"Posledná skúšobná kópia nastavená ako ostrá prevádzka na záverečnú kontrolu pred nasadením.","also":["predprodukčné prostredie","staging environment"]},{"id":"artifact","g":"change","word":"Výstup zostavenia","text":"Súbor či balík vytvorený zostavením, pripravený na uloženie, kontrolu alebo nasadenie.","also":["výstupy zostavenia","build artifacts"]},{"id":"hotfix","g":"change","word":"Naliehavá oprava","text":"Rýchlo nasadená oprava mimo bežného plánu, pretože je pokazené niečo dôležité.","also":["naliehavé opravy","naliehavej opravy","hotfixy","hotfixes"]},{"id":"patch","g":"change","word":"Záplata","text":"Malá aktualizácia opravujúca chybu či bezpečnostnú dieru. Bezpečnostné záplaty je dôležité aplikovať rýchlo.","also":["záplaty","záplat","bezpečnostná záplata","patches","security patch","security patches"]},{"id":"version","g":"change","word":"Číslo verzie","text":"Označenie ako 2.4.1 určuje vydanie. Prvé číslo sa často mení pri veľkých zmenách, posledné pri drobných opravách.","also":["čísla verzií","sémantické verziovanie","version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Poznámky k vydaniu","text":"Stručný zrozumiteľný zoznam zmien pre používateľov vrátane opráv a známych obmedzení. Nazýva sa aj denník zmien.","also":["denník zmien","changelog","change log"]},{"id":"flag","g":"change","word":"Prepínač funkcie","text":"Vypínač funkcie umožňujúci nasadiť ju skrytú a neskôr zapnúť či vypnúť bez nového vydania.","also":["prepínače funkcií","prepínača funkcie","feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Oprava novou verziou","text":"Oprava chybného vydania rýchlym vydaním novej opravenej verzie namiesto návratu k starej.","also":["oprava novou verziou","rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Kanárikové vydanie","text":"Zmena sa najprv sprístupní malej skupine a až po overení všetkým. Názov pripomína kanáriky varujúce baníkov pred nebezpečenstvom.","also":["kanárikové vydania","canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Modro-zelené nasadenie","text":"Dve kópie ostrej prevádzky umožňujú naraz presmerovať ľudí na novú a pri probléme okamžite späť.","also":["modro-zelené nasadenie","blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Nasadenie bez výpadku","text":"Nasadenie novej verzie bez prerušenia služby používateľom.","also":["bez výpadku","zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Riadenie zmien","text":"Pomoc, aby zmeny dopadli dobre: posúdenie rizika, získanie správneho schválenia a výber vhodného času. Nazýva sa aj riadenie zmien (change management).","also":["riadenie zmien","change management"]},{"id":"cab","g":"change","word":"Poradný výbor pre zmeny (CAB)","text":"Skupina, ktorá posudzuje dôležité zmeny a rozhoduje, či a kedy môžu pokračovať.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Štandardná zmena","text":"Málo riziková zmena vykonávaná vždy rovnako overeným postupom, preto je schválená vopred.","also":["štandardné zmeny","standard changes"]},{"id":"normchange","g":"change","word":"Bežná zmena","text":"Zmena, ktorú treba pred vykonaním preveriť a schváliť.","also":["bežné zmeny","normal changes"]},{"id":"emergchange","g":"change","word":"Núdzová zmena","text":"Okamžitá zmena na nápravu či odvrátenie vážnych problémov so zrýchleným schvaľovaním.","also":["núdzové zmeny","emergency changes"]},{"id":"automation","g":"change","word":"Automatizácia","text":"Počítač vykonáva opakovanú úlohu sám, rýchlejšie a vždy rovnakým spôsobom.","also":["automatizovaný","automated"],"noTip":1},{"id":"infra","g":"change","word":"Infraštruktúra","text":"Zariadenia, siete a služby, na ktorých beží softvér.","also":["infra"]},{"id":"iac","g":"change","word":"Infraštruktúra ako kód (IaC)","text":"Opis serverov a nastavení v súboroch pri kóde, aby sa dali zakaždým obnoviť rovnako.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Prenájom počítačov, úložiska a služieb cez internet od veľkého poskytovateľa namiesto vlastných zariadení.","also":["the cloud","cloud computing","cloudové služby"]},{"id":"provider","g":"change","word":"Poskytovateľ cloudu","text":"Firma prenajímajúca výpočtové služby cez internet, napríklad AWS, Microsoft Azure alebo Google Cloud.","also":["poskytovatelia cloudu","cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Miesto, kde aplikácia či web beží a je dostupný ľuďom, zvyčajne prenajaté od firmy.","also":["hostovaný"]},{"id":"domain","g":"change","word":"Doménové meno","text":"Webová adresa, ktorú ľudia píšu, napríklad example.com. Prenajíma sa vždy na rok, preto ju treba pravidelne obnovovať.","also":["doména","doménové mená","domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Internetový adresár premieňajúci názov ako example.com na adresu správneho počítača. Skratka znamená systém doménových mien.","also":["systém doménových mien","domain name system"]},{"id":"container","g":"change","word":"Kontajner","text":"Uzavretý balík aplikácie so všetkým potrebným, aby všade fungovala rovnako. Najznámejším nástrojom je Docker.","also":["kontajnery","kontajnera","containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtuálny počítač (VM)","text":"Napodobnený počítač vo vnútri skutočného, takže jeden veľký stroj môže fungovať ako viacero.","also":["VM","VMs","virtuálne počítače","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Spúšťanie kódu bez vlastnej správy serverov: poskytovateľ ho spustí podľa potreby a platíš za použitie."},{"id":"lb","g":"change","word":"Rozdeľovač záťaže","text":"Rozdeľuje návštevníkov medzi servery, aby sa žiadny nepreťažil.","also":["rozdeľovače záťaže","load balancers"]},{"id":"cache","g":"change","word":"Vyrovnávacia pamäť","text":"Blízke úložisko nedávnych výsledkov, aby sa nemuseli znovu získavať či počítať. Vymazanie môže napraviť zastarané zobrazenie stránky.","also":["cache","vyrovnávacej pamäte","keš","caches","caching","cached"]},{"id":"cdn","g":"change","word":"Sieť na doručovanie obsahu (CDN)","text":"Celosvetová sieť serverov s kópiami stránok a obrázkov blízko návštevníkov pre rýchle načítanie.","also":["CDN"]},{"id":"migration","g":"change","word":"Migrácia","text":"Presun údajov či systémov zo starého usporiadania do nového alebo opatrná zmena štruktúry databázy.","also":["migrácie","migrácií","migrations","database migration"]},{"id":"service","g":"run","word":"Služba","text":"Niečo, čo si postavil a na čo sa ľudia spoliehajú, napríklad web alebo aplikácia, o čo sa niekto stará, aby to stále fungovalo. Zaškrtni „Tento projekt je služba“ a napíš, čo ponúka, kto ju používa a kto má pohotovosť.","also":["služby","servis"]},{"id":"uptimepct","g":"run","word":"Uptime (čas prevádzky)","text":"Podiel času, keď služba funguje, zvyčajne v percentách. Aj 99,9 % pripúšťa približne 43 minút výpadku mesačne.","also":["percento dostupnosti","čas prevádzky","uptime percentage"]},{"id":"uptime","g":"run","word":"Kontrola dostupnosti","text":"Automatická kontrola každých pár minút, či tvoja služba ešte odpovedá. Ak niekoľkokrát za sebou zlyhá, AI-gile sám otvorí kartu incidentu.","also":["kontroly dostupnosti","uptime checks"]},{"id":"statuspage","g":"run","word":"Stránka stavu","text":"Verejná stránka, ktorá ukazuje, či služba funguje (zelená, oranžová alebo červená), spolu s poslednou správou, aby si to ľudia, ktorí ju používajú, mohli pozrieť namiesto pýtania sa.","also":["stránky stavu","stavová stránka","status page"]},{"id":"desk","g":"run","word":"Podatelňa","text":"Miesto, kam prichádzajú otázky a hlásenia od ľudí, ktorí používajú tvoju službu. AI-gile každé zaradí ako požiadavku, incident alebo nápad a upozorní, keď to vyzerá ako niečo, čo už bolo nahlásené.","also":["service desk","helpdesk","zákaznícka podpora"]},{"id":"svcrequest","g":"run","word":"Požiadavka na službu","text":"Keď niekto žiada niečo bežné, napríklad nový účet alebo trochu pomoci, namiesto hlásenia, že je niečo pokazené. Čaká, kým príde na rad; incident má prednosť.","also":["požiadavky na službu"]},{"id":"incident","g":"run","word":"Incident","text":"Niečo práve nefunguje používateľom, napríklad nefunkčný či veľmi pomalý web. Karta incidentu 🔥 ide pred ostatné: najprv treba obnoviť fungovanie.","also":["incidenty"]},{"id":"major","g":"run","word":"Závažný incident","text":"Veľký incident: zasiahnutých je veľa ľudí alebo sú v ohrození peniaze či dáta. Jedno tlačidlo naň postaví všetky tímy (roj), zobudí toho, kto má pohotovosť, a každých 30 minút si vypýta správu o stave.","also":["závažné incidenty","major incident"]},{"id":"oncall","g":"run","word":"Pohotovosť","text":"Byť ten, kto odpovedá, keď sa niečo pokazí, aj v noci. Každá služba má člena tímu s pohotovosťou, ktorého pri jej incidentoch zobudia ako prvého.","also":["pohotovostný","on call","on-call"]},{"id":"replyby","g":"run","word":"Termín odpovede","text":"Ako dlho môže karta čakať na prvú odpoveď, napríklad hodinu pri incidente. Potom dostane červené hodiny, aby sa nič potichu nezabudlo. Hovorí sa tomu aj cieľ odozvy.","also":["termíny odpovedí","cieľ odozvy","ciele odozvy"]},{"id":"postmortem","g":"run","word":"Rozbor incidentu","text":"Krátky pohľad späť po incidente: čo sa stalo, čo pomohlo a čo zmeniť, bez obviňovania kohokoľvek. Bez neho sa incident nedá zavrieť. Často sa mu hovorí aj post-mortem.","also":["rozbory incidentov","post-mortem","postmortem"]},{"id":"problem","g":"run","word":"Problém","text":"Skrytá príčina za jedným alebo viacerými incidentmi. Karta 🧩 problému spojí incidenty, ktoré sa stále vracajú, aby sa príčina našla a opravila nadobro.","also":["problémy"],"noTip":1},{"id":"rootcause","g":"run","word":"Príčina","text":"Skutočný dôvod, prečo sa niečo pokazilo, nie len to, čo si videl, že nejde. Oprav príčinu a incident sa prestane vracať.","also":["príčiny","koreňová príčina","root cause"]},{"id":"workaround","g":"run","word":"Náhradné riešenie","text":"Spôsob, ako udržať veci v chode, kým nie je hotová skutočná oprava, napríklad reštartovať niečo, keď sa to zasekne. Zapíše sa na kartu problému, aby to nikto nemusel vymýšľať znova.","also":["náhradné riešenia","workaround","obchádzka"]},{"id":"knownerror","g":"run","word":"Známa chyba","text":"Problém, ktorého príčina je jasná, ale ešte nie je opravený, zvyčajne so zapísaným náhradným riešením. 🧩 Známe chyby ich vypisujú, aby všetci použili náhradné riešenie namiesto ďalšieho pátrania.","also":["známe chyby","known error"]},{"id":"runbook","g":"run","word":"Runbook","text":"Návod krok za krokom, ako opraviť známy druh problému, aby sa to zakaždým urobilo rovnako a rýchlo. Po veľkom incidente ti ho tím môže navrhnúť na odsúhlasenie.","also":["runbooky","postup","prevádzkový postup"]},{"id":"ci","g":"run","word":"Konfiguračná položka","text":"Jedna vec, na ktorej tvoja služba závisí, napríklad server, doména, certifikát, kľúč alebo dodávateľ. 🗂️ Konfiguračné položky ich zobrazujú podľa služby, takže vidíš, čoho sa incident týka a čo treba obnoviť alebo zálohovať.","also":["konfiguračné položky"]},{"id":"expiry","g":"run","word":"Dátum platnosti","text":"Dátum, keď niečo bez obnovenia prestane fungovať, napríklad bezpečnostný certifikát webu alebo jeho doména. AI-gile tieto dátumy sleduje a 30 dní vopred vytvorí na každé obnovenie jednu kartu, aby nič neprestalo fungovať nečakane.","also":["dátumy platnosti","platnosť","koniec platnosti","sledovanie platnosti"]},{"id":"backup","g":"run","word":"Záloha","text":"Uložená kópia tvojich dát zo skoršia, na ktorú sa dá vrátiť, ak sa niečo stratí alebo poškodí. AI-gile robí zálohu tvojich boardov každý deň.","also":["zálohy","backup","zálohovanie"]},{"id":"restore","g":"run","word":"Obnovenie","text":"Vrátenie dát zo zálohy. Záloha naozaj platí, až keď vieš, že sa z nej dá obnoviť, takže sa oplatí to občas vyskúšať.","also":["obnoviť","obnovené","restore"]},{"id":"svcreview","g":"run","word":"Revízia služby","text":"Pohľad späť na jeden mesiac služby: otvorené a opravené incidenty, ako rýchlo ľudia dostali odpoveď, dostupnosť a použité tokeny. Mesačná revízia to ukazuje pre každú službu.","also":["revízie služby","mesačná revízia","mesačné revízie"]},{"id":"accessreview","g":"run","word":"Kontrola prístupov","text":"Každých 90 dní sa overí, kto sa ešte dostane dnu: odkazy na zdieľanie, roly kamarátov aj uložené heslá a kľúče. Každý prístup ponecháš alebo odstrániš, aby starý prístup nezostal visieť.","also":["kontroly prístupov"]},{"id":"improvements","g":"run","word":"Zoznam zlepšení","text":"Všetko, v čom sa tím rozhodol zlepšiť, na jednom mieste: návrhy z retra, úlohy z revízií a opravy problémov, každé so svojím stavom. Nájdeš to pod 📈 Zlepšenia.","also":["zoznamy zlepšení","zlepšenia"]},{"id":"tokencap","g":"run","word":"Limit tokenov","text":"Mesačný limit tokenov, ktoré môžu agenti služby použiť. Pri 80 % dostaneš upozornenie; pri 100 % ich práca na pozadí počká do ďalšieho mesiaca alebo kým limit nezvýšiš.","also":["limity tokenov"]},{"id":"svcmgmt","g":"run","word":"Riadenie služieb","text":"Všetko potrebné na každodennú užitočnosť a fungovanie služby pre ľudí, ktorí sa na ňu spoliehajú.","also":["správa služby"]},{"id":"itil","g":"run","word":"ITIL","text":"Rozšírená príručka dobrej správy služieb vrátane incidentov, problémov a zmien. Názov pôvodne znamenal IT Infrastructure Library."},{"id":"itsm","g":"run","word":"Riadenie IT služieb (ITSM)","text":"Prevádzka technológií ako služby pre ľudí s jasnými postupmi pre požiadavky, incidenty, zmeny a zlepšenia.","also":["ITSM"]},{"id":"managed","g":"run","word":"Spravovaná služba","text":"Služba, ktorú za teba prevádzkuje a spravuje niekto iný podľa dohody o kvalite.","also":["spravované služby","managed services"]},{"id":"svcowner","g":"run","word":"Vlastník služby","text":"Človek zodpovedný za službu ako celok: fungovanie, náklady a zlepšovanie.","also":["vlastníci služby","service owners"]},{"id":"sla","g":"run","word":"Dohoda o úrovni služby (SLA)","text":"Písomný sľub zákazníkom, napríklad dostupnosť 99,9 % času alebo odpoveď do hodiny, často s náhradou pri porušení.","also":["SLA","SLAs","dohody o úrovni služby","service level agreement"]},{"id":"slo","g":"run","word":"Cieľ úrovne služby (SLO)","text":"Vlastný cieľ tímu pre kvalitu služby za obdobie, zvyčajne o niečo prísnejší než SLA pre istotu.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Ukazovateľ úrovne služby (SLI)","text":"Skutočné namerané číslo porovnávané s cieľom, napríklad podiel úspešne načítaných návštev.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Dostupnosť","text":"Či ľudia môžu službu používať, keď ju potrebujú; často sa meria ako uptime.","also":["vysoká dostupnosť","high availability"]},{"id":"downtime","g":"run","word":"Čas odstávky","text":"Čas, keď služba nefunguje alebo je vypnutá, plánovane či neplánovane.","also":["čas odstávky","down time"]},{"id":"errorbudget","g":"run","word":"Rozpočet chýb","text":"Malé množstvo zlyhaní dovolené cieľom spoľahlivosti. Kým zostáva rezerva, môžeš pri zmenách riskovať; po vyčerpaní spomalíš.","also":["rozpočty chýb","error budgets"]},{"id":"outage","g":"run","word":"Výpadok","text":"Obdobie, keď služba používateľom nefunguje alebo je vážne narušená.","also":["výpadky","výpadku","výpadkov","outages"]},{"id":"degraded","g":"run","word":"Zhoršená prevádzka","text":"Služba funguje, ale zle: pomaly alebo s nefunkčnými časťami.","also":["zhoršená služba","degraded service"]},{"id":"monitoring","g":"run","word":"Monitorovanie","text":"Neustále automatické sledovanie služby na odhalenie problémov, ideálne skôr než si ich všimnú používatelia.","also":["monitorovaný"]},{"id":"observability","g":"run","word":"Pozorovateľnosť","text":"Ako dobre vieš zvonka zistiť vnútorné dianie systému pomocou záznamov, čísel a trás požiadaviek.","also":["o11y"]},{"id":"log","g":"run","word":"Log (záznam)","text":"Priebežný denník činnosti programu, ktorý pomáha zistiť, čo sa pokazilo.","also":["log","logy","logov","záznamy","záznam činnosti","protokol","logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Stopa požiadavky","text":"Záznam cesty jednej požiadavky časťami systému krok za krokom, ktorý ukazuje spomalenia.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latencia","text":"Čas čakania na odpoveď, napríklad od kliknutia po zobrazenie stránky."},{"id":"alert","g":"run","word":"Upozornenie","text":"Automatická správa, že niečo potrebuje pozornosť, napríklad neodpovedajúci web.","also":["upozornenia","upozornení","alerty","alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Únava z upozornení","text":"Toľko upozornení, že ich ľudia začnú ignorovať vrátane tých dôležitých.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Prehľadový panel","text":"Obrazovka s najdôležitejšími číslami a stavmi na prvý pohľad.","also":["prehľadové panely","dashboardu","dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Privolanie pohotovosti","text":"Naliehavé zavolanie alebo zobudenie človeka v pohotovosti kvôli problému.","also":["paged"]},{"id":"escalation","g":"run","word":"Eskalácia","text":"Prizvanie niekoho s väčšími znalosťami či právomocou, keď sa problém na danej úrovni nedá vyriešiť dosť rýchlo.","also":["eskalovať","eskalácie","escalate","escalated"]},{"id":"triage","g":"run","word":"Triedenie problémov","text":"Rýchle zoradenie nových problémov podľa naliehavosti a dôležitosti, aby sa najhoršie riešili prvé.","also":["triaged"]},{"id":"impact","g":"run","word":"Dosah","text":"Ako veľmi niečo ovplyvňuje ľudí: koľkých a ako vážne.","noTip":1},{"id":"urgency","g":"run","word":"Naliehavosť","text":"Ako rýchlo treba niečo riešiť. Dosah a naliehavosť spolu určujú prioritu.","noTip":1},{"id":"plevels","g":"run","word":"Úrovne priority (P1, P2…)","text":"Označenia naliehavosti problému. P1 je najvážnejší a vyžaduje okamžitý zásah.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Rad tiketov","text":"Zoznam požiadaviek a incidentov čakajúcich na prevzatie.","also":["rady tiketov","ticket queues"]},{"id":"tiers","g":"run","word":"Prvá a druhá úroveň podpory","text":"Prvá úroveň prijíma hlásenia a rieši jednoduché veci; druhá má hlbšie znalosti na zložitejšie problémy. Nazývajú sa aj tier 1 a tier 2.","also":["prvá línia","druhá línia","first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Vedúci riešenia incidentu","text":"Jeden človek riadi riešenie incidentu, aby každý vedel, kto rozhoduje a kto čo robí.","also":["vedúci incidentov","incident commanders"]},{"id":"responsetime","g":"run","word":"Čas prvej reakcie","text":"Čas, kým niekto prvýkrát prevezme požiadavku alebo incident.","also":["časy reakcie","response times"]},{"id":"resolution","g":"run","word":"Čas vyriešenia","text":"Čas úplného vyriešenia požiadavky či incidentu od nahlásenia po opravu.","also":["časy vyriešenia","resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Priemerný čas obnovy (MTTR)","text":"Priemerný čas potrebný na obnovenie služby po poruche. MTTR má viac významov, preto povedz, čo presne meriaš.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Priemerný čas medzi poruchami (MTBF)","text":"Ako dlho služba priemerne funguje pred poruchou.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Databáza správy konfigurácie (CMDB)","text":"Zoznam všetkých konfiguračných položiek a ich prepojení, aby bolo vidno vzájomné závislosti.","also":["CMDB"]},{"id":"asset","g":"run","word":"Aktívum","text":"Čokoľvek hodnotné, čo vlastníš alebo platíš na prevádzku služby, napríklad notebook, licencia či doména.","also":["aktíva","aktív","assets"],"noTip":1},{"id":"capplan","g":"run","word":"Plánovanie kapacity","text":"Zabezpečenie dostatku výpočtového výkonu, úložiska a ľudí pre budúce potreby.","also":["kapacitný plán","capacity plan"]},{"id":"scaling","g":"run","word":"Škálovanie","text":"Zvládanie väčšieho počtu používateľov posilnením jedného stroja alebo pridaním ďalších strojov.","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Kontinuita podnikania","text":"Plány na zachovanie dôležitých činností pri vážnych problémoch, napríklad strate kancelárie, dodávateľa či počítačov.","also":["plán kontinuity","business continuity plan"]},{"id":"dr","g":"run","word":"Obnova po havárii (DR)","text":"Plán a nástroje na obnovenie služby po vážnej udalosti, napríklad strate celého dátového centra.","also":["obnova po havárii","disaster recovery"]},{"id":"rto","g":"run","word":"Cieľový čas obnovy (RTO)","text":"Najdlhší prípustný výpadok služby po havárii, po ktorom už musí opäť fungovať.","also":["RTO"]},{"id":"rpo","g":"run","word":"Cieľový bod obnovy (RPO)","text":"Koľko najnovších údajov si môžeš dovoliť stratiť, vyjadrené časom. Jedna hodina znamená zálohovanie aspoň každú hodinu.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancia","text":"Pripravené náhradné časti, napríklad druhý server, aby jedna porucha nezastavila službu."},{"id":"failover","g":"run","word":"Prepnutie na zálohu","text":"Automatické prepnutie na náhradný systém, keď bežný zlyhá.","also":["prepnutie na zálohu","fail over"]},{"id":"spof","g":"run","word":"Jediný bod zlyhania","text":"Časť, ktorej porucha zastaví všetko, pretože nemá náhradu.","also":["jediné body zlyhania","single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Okno údržby","text":"Vopred oznámený čas, keď môže byť služba kvôli údržbe pozastavená či pomalšia.","also":["okná údržby","plánovaná údržba","maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Odovzdanie","text":"Odovzdanie práce, vedomostí a zodpovednosti ďalšiemu človeku či tímu, aby sa nič nestratilo.","also":["handovers"]},{"id":"kb","g":"run","word":"Znalostná báza","text":"Zbierka návodov a odpovedí pre používateľov aj tím.","also":["znalostné bázy","knowledge bases"]},{"id":"csat","g":"run","word":"Spokojnosť zákazníkov (CSAT)","text":"Hodnotenie spokojnosti od používateľov, často po uzavretí požiadavky.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Dodávateľ","text":"Externá firma, na ktorú sa spoliehaš, napríklad poskytovateľ hostingu. Nazýva sa aj tretia strana.","also":["dodávatelia","dodávateľa","dodávateľov","suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Ukončenie služby","text":"Bezpečné trvalé vypnutie služby: oznámenie používateľom, vyriešenie údajov a prístupov a zastavenie nákladov.","also":["vyraďovanie služby","retiring a service"]},{"id":"eol","g":"run","word":"Koniec životnosti (EOL)","text":"Výrobca prestane produkt aktualizovať či podporovať, preto ho treba nahradiť.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Kybernetická bezpečnosť","text":"Ochrana systémov a údajov pred neoprávneným vstupom, krádežou či poškodením.","also":["kybernetická bezpečnosť","cyber security"]},{"id":"authn","g":"sec","word":"Autentifikácia","text":"Overenie, kto niekto je, zvyčajne heslom či kódom. Často sa skracuje na authn.","also":["overenie totožnosti","authn"]},{"id":"authz","g":"sec","word":"Autorizácia","text":"Overenie, čo človek smie robiť, keď už poznáš jeho totožnosť. Často sa skracuje na authz.","also":["overenie oprávnení","authz","authorization"]},{"id":"mfa","g":"sec","word":"Viacfaktorové overenie (MFA)","text":"Prihlásenie dvoma či viacerými dôkazmi, napríklad heslom a kódom v telefóne. Pri dvoch dôkazoch sa hovorí aj o dvojfaktorovom overení (2FA).","also":["MFA","2FA","dvojfaktorové overenie","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Jednotné prihlásenie (SSO)","text":"Jedno prihlásenie pre viacero systémov, napríklad pracovným účtom všade.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Správca hesiel","text":"Aplikácia, ktorá vytvára silné heslá a pamätá si ich za teba.","also":["správcovia hesiel","password managers"]},{"id":"secret","g":"sec","word":"Tajomstvo","text":"Heslo, kľúč či iný súkromný kód umožňujúci programu prístup. Nikdy sa nesmie zdieľať ani zapisovať do kódu.","also":["tajomstvá","tajomstiev","tajný údaj","tajné údaje","secret","secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"Kľúč API","text":"Tajný kód umožňujúci programu používať API inej služby a určujúci, kto ho používa a platí.","also":["kľúče API","API keys"]},{"id":"accesstoken","g":"sec","word":"Prístupový token","text":"Dočasná vstupenka potvrdzujúca prístup programu bez opakovaného zadávania hesla. Nie je to token AI.","also":["prístupové tokeny","access tokens"]},{"id":"encryption","g":"sec","word":"Šifrovanie","text":"Premena informácií tak, aby ich prečítal iba človek so správnym kľúčom.","also":["šifrovaný","zašifrovať","encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"Bezpečný prenos webových stránok označený zámkom v prehliadači, aby ich nikto cestou nečítal ani nemenil."},{"id":"cert","g":"sec","word":"Certifikát SSL/TLS","text":"Digitálny preukaz totožnosti webu umožňujúci HTTPS. Má dátum platnosti, preto ho treba obnovovať.","also":["certifikát TLS","certifikát SSL","certifikáty","TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Oprávnenia","text":"Pravidlá určujúce, kto čo smie vidieť alebo meniť.","also":["oprávnenie","permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Najmenšie oprávnenia","text":"Každý človek či program dostane iba nevyhnutný prístup a len na potrebný čas.","also":["princíp najmenších oprávnení","principle of least privilege"]},{"id":"rbac","g":"sec","word":"Riadenie prístupu podľa rolí (RBAC)","text":"Prideľovanie prístupu podľa roly, napríklad čitateľ či editor, namiesto nastavovania každému zvlášť.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Zraniteľnosť","text":"Slabina, ktorú niekto môže využiť na vniknutie alebo spôsobenie škody.","also":["zraniteľnosti","zraniteľností","vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"Slabina známa útočníkom skôr, než mali tvorcovia čas ju opraviť.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malvér","text":"Škodlivý softvér, napríklad vírusy, určený na poškodzovanie, špehovanie či krádež."},{"id":"ransomware","g":"sec","word":"Ransomvér","text":"Škodlivý program zamykajúci súbory a žiadajúci výkupné za odomknutie. Najlepšou obranou sú dobré zálohy.","also":["ransomvérový útok","ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Falošné správy, ktoré sa snažia vylákať heslá či peniaze alebo prinútiť otvoriť niečo škodlivé.","also":["podvodný e-mail","phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Sociálne inžinierstvo","text":"Oklamanie ľudí namiesto počítačov na získanie prístupu, napríklad falošným telefonátom „IT podpory“."},{"id":"firewall","g":"sec","word":"Firewall","text":"Ochrana rozhodujúca, ktorá sieťová komunikácia smie dnu či von.","also":["firewally","firewallu","firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Virtuálna súkromná sieť: súkromné šifrované spojenie cez internet, často na bezpečný prístup k pracovným systémom.","also":["virtuálna súkromná sieť","virtual private network"]},{"id":"ddos","g":"sec","word":"Odmietnutie služby (DoS, DDoS)","text":"Zaplavenie služby falošnou prevádzkou, aby ju skutoční ľudia nemohli používať. DDoS prichádza z mnohých počítačov naraz.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetračný test","text":"Najatie odborníkov, ktorí s dovolením skúšajú preniknúť dnu, aby našli slabiny pred útočníkmi.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Bezpečnostný audit","text":"Dôkladné overenie ochrany podľa zoznamu osvedčených postupov.","also":["bezpečnostné audity","security audits"]},{"id":"threatmodel","g":"sec","word":"Modelovanie hrozieb","text":"Premyslenie, kto by mohol zaútočiť, ako a čo by tomu zabránilo.","also":["model hrozieb","threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Únik údajov","text":"Súkromné informácie sa dostanú k nepovolaným ľuďom alebo sa bez povolenia stratia či zmenia.","also":["úniky údajov","úniku údajov","data breaches"]},{"id":"pii","g":"sec","word":"Osobné údaje","text":"Informácie o identifikovateľnom človeku, napríklad meno, e-mail či poloha. Označujú sa aj PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"Európsky zákon o osobných údajoch (Spojené kráľovstvo má vlastnú verziu): zbieraj len to, čo potrebuješ, chráň to a umožni ľuďom ich údaje vidieť alebo vymazať.","also":["všeobecné nariadenie o ochrane údajov","General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Ochrana údajov","text":"Správna starostlivosť o osobné údaje v súlade so zákonom.","also":["zákon o ochrane údajov","data protection law"]},{"id":"privacypolicy","g":"sec","word":"Zásady ochrany súkromia","text":"Verejná stránka vysvetľujúca, aké osobné údaje zbieraš, prečo a čo s nimi robíš.","also":["vyhlásenie o súkromí","privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Súhlas","text":"Jasné a slobodné áno človeka s konkrétnym použitím jeho údajov. Môže ho kedykoľvek odvolať.","also":["dobrovoľné prihlásenie","opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Súbor cookie","text":"Malý súbor uložený webom v prehliadači na zapamätanie vecí, napríklad prihlásenia. Niektoré vyžadujú súhlas vopred.","also":["súbory cookie","cookies","cookie"],"noTip":1},{"id":"minimisation","g":"sec","word":"Minimalizácia údajov","text":"Zbieranie a uchovávanie iba skutočne potrebných osobných údajov.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Uchovávanie údajov","text":"Ako dlho sa údaje uchovávajú pred vymazaním. Uchovávať ich iba nevyhnutný čas je bezpečnejšie a často aj zákonom požadované.","also":["lehota uchovávania","retention period"]},{"id":"anon","g":"sec","word":"Anonymizácia","text":"Úprava údajov tak, aby sa z nich už rozumne nedala určiť totožnosť človeka.","also":["anonymizované","anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymizácia","text":"Nahradenie mien a iných údajov kódmi s oddelene uloženým kľúčom na spätné spojenie. Stále ide o osobné údaje.","also":["pseudonymizované","pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Zmluva o spracúvaní údajov (DPA)","text":"Zmluva určujúca, ako dodávateľ smie v tvojom mene spracúvať osobné údaje.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Posúdenie vplyvu na ochranu údajov (DPIA)","text":"Dôkladné posúdenie pred začiatkom, ako použitie osobných údajov ovplyvní ľudí a ako znížiť riziká.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Auditný záznam","text":"Záznam, kto čo kedy urobil, na neskoršie overenie činností.","also":["auditné záznamy","audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Súlad s pravidlami","text":"Dodržiavanie platných zákonov, pravidiel a noriem aj schopnosť to preukázať.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"Známa medzinárodná norma riadenia informačnej bezpečnosti. Firmy podľa nej môžu získať certifikát.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"Americká správa overená externými audítormi, ktorá dokladá riadnu ochranu zákazníckych údajov vo firme.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Agent","text":"AI samostatne riešiaca úlohu: číta kód, robí zmeny, spúšťa kontroly a hlási výsledok. Jej práca sa stále kontroluje.","also":["agenti","agentov"]},{"id":"token","g":"ai","word":"Token","text":"Drobné kúsky textu, ktoré AI číta a píše, každý približne tri štvrtiny slova. Využitie AI sa počíta v tokenoch, takže menej tokenov ti nechá viac z tvojho plánu.","also":["tokeny","tokenov"]},{"id":"hook","g":"ai","word":"Hook","text":"Malý príkaz spúšťaný automaticky v určený okamih, napríklad pri začiatku relácie AI, aby tím dostal tvoje komentáre.","also":["hooky","hooku"]},{"id":"ai","g":"ai","word":"Umelá inteligencia (AI)","text":"Počítačové systémy vykonávajúce činnosti zvyčajne spájané s ľuďmi, napríklad písanie, odpovedanie či rozpoznávanie obrázkov.","also":["AI","umelá inteligencia","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Strojové učenie (ML)","text":"Učenie počítačov rozpoznávať vzory z množstva príkladov namiesto zadávania presných pravidiel.","also":["strojové učenie","machine learning"]},{"id":"model","g":"ai","word":"Model","text":"Naučený „mozog“ AI vytvorený z obrovského množstva príkladov. Modely sa líšia schopnosťami, rýchlosťou aj cenou.","also":["modely","modelu","model AI","models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Veľký jazykový model (LLM)","text":"Model AI naučený na obrovskom množstve textu, aby vedel čítať a písať.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generatívna AI","text":"AI tvoriaca nové veci, napríklad texty, obrázky či kód, namiesto samotného triedenia alebo rozpoznávania.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"Program, s ktorým sa rozprávaš bežným jazykom písomne alebo hlasom.","also":["chatboty","chatbota","chatbots"]},{"id":"prompt","g":"ai","word":"Prompt (zadanie)","text":"Čo odovzdáš AI: otázku či pokyny spolu s prílohami. Jasnejšie zadania zvyčajne prinášajú lepšie odpovede.","also":["prompty","promptu","prompts"]},{"id":"prompteng","g":"ai","word":"Tvorba promptov","text":"Zručnosť písať zadania tak, aby prinášali spoľahlivé a užitočné výsledky.","also":["zadávanie promptov"]},{"id":"sysprompt","g":"ai","word":"Systémový prompt","text":"Pokyny na pozadí pred začiatkom rozhovoru určujúce rolu a pravidlá AI. Majú väčšiu váhu než tvoj text.","also":["systémové pokyny","system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Kontext","text":"Všetko, čo AI pri práci vidí: pokyny, tvoje správy, prečítané súbory a predchádzajúce odpovede.","noTip":1},{"id":"ctxwin","g":"ai","word":"Kontextové okno","text":"Koľko si AI naraz udrží v pamäti, merané v tokenoch. Nad limitom sa staršie časti vynechajú či zhrnú.","also":["kontextové okná","context windows"]},{"id":"session","g":"ai","word":"Relácia","text":"Jeden pracovný rozhovor s AI od začiatku do konca. Nová relácia začína s čistou pamäťou.","also":["relácie","relácií","sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Pamäť","text":"Poznámky uchovávané medzi reláciami, vďaka ktorým si AI pamätá tvoje preferencie a minulé rozhodnutia.","noTip":1},{"id":"hallucination","g":"ai","word":"Halucinácia","text":"AI sebavedomo tvrdí niečo vymyslené či nesprávne. Dôležité fakty si overuj.","also":["halucinácie","halucinácií","halucinovať","hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Trénovanie","text":"Učenie modelu pomocou obrovského množstva príkladov ešte pred jeho používaním.","also":["natrénovaný","trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Trénovacie údaje","text":"Príklady, z ktorých sa model učil. Jeho znalosti končia dátumom zberu týchto údajov.","also":["trénovacia množina","training set"]},{"id":"cutoff","g":"ai","word":"Hranica znalostí","text":"Dátum, po ktorý siahajú vstavané znalosti AI. Neskoršie udalosti pozná len po dohľadaní.","also":["koniec trénovacích údajov","training cutoff"]},{"id":"finetune","g":"ai","word":"Dolaďovanie modelu","text":"Dodatočné trénovanie existujúceho modelu na vlastných príkladoch na zlepšenie konkrétnej úlohy.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inferencia","text":"Skutočné používanie modelu AI na odpovedanie, na rozdiel od jeho trénovania.","also":["inferencia modelu","model inference"]},{"id":"tooluse","g":"ai","word":"Používanie nástrojov","text":"AI môže aj konať: spúšťať príkazy, čítať súbory či hľadať na webe pomocou nástrojov aplikácie.","also":["volanie nástrojov","tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"Pomocná AI, ktorej hlavná AI odovzdá menšiu úlohu a dostane výsledok späť.","also":["subagenti","subagenta","subagentov","subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Viacagentový systém","text":"Viacero AI spolupracujúcich na jednej práci, každá s vlastnou časťou, podobne ako malý tím.","also":["viacagentový systém","multi-agent system"]},{"id":"autonomy","g":"ai","word":"Samostatnosť","text":"Koľko smie AI urobiť sama, kým sa musí opýtať človeka.","also":["autonómny","autonomous"]},{"id":"hitl","g":"ai","word":"Človek v rozhodovacom procese","text":"Zapojenie človeka, ktorý v dôležitých bodoch kontroluje alebo schvaľuje činnosť AI. V AI-gile si to ty.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Ochranné pravidlá","text":"Obmedzenia a kontroly bezpečnosti AI, napríklad schválenie pred nasadením. Znižujú riziko chýb, ale nevylučujú ich.","also":["ochranné pravidlo","guardrail"]},{"id":"rag","g":"ai","word":"Generovanie podporené vyhľadávaním (RAG)","text":"AI si pred odpoveďou vyhľadá informácie v tvojich dokumentoch, aby vychádzala z tvojich faktov.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding (číselné vyjadrenie významu)","text":"Premena textu na zoznam čísel zachytávajúci význam, aby počítač našiel významovo podobné veci.","also":["embeddingy","embeddingu","embeddings"]},{"id":"vectordb","g":"ai","word":"Vektorová databáza","text":"Databáza na prehľadávanie číselných vyjadrení významu a hľadanie významovo podobného obsahu.","also":["vektorové databázy","vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"Spoločný spôsob pripájania nástrojov a zdrojov údajov k aplikáciám AI, aby ich AI mohla používať.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Teplota","text":"Nastavenie odvážnosti odpovedí AI: nízka dáva stálejšie, vysoká rozmanitejšie odpovede. Ani jedna nezaručuje správnosť.","also":["teplota modelu","model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodálny","text":"Schopnosť pracovať s viacerými druhmi informácií, napríklad textom, obrázkami a zvukom.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Vyhodnocovanie (eval)","text":"Plánovaná skúška AI na vybraných príkladoch na porovnanie modelov alebo zadaní.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Zaujatosť","text":"Keď AI alebo človek nespravodlivo uprednostňuje jednu stranu, často pre skúsenosti, z ktorých sa učil.","also":["zaujatý","biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Zodpovedná AI","text":"Férové, bezpečné a čestné používanie AI, pri ktorom za výsledky stále zodpovedajú ľudia.","also":["etická AI","ethical AI"]},{"id":"injection","g":"ai","word":"Vloženie škodlivých pokynov","text":"Trik, pri ktorom skryté pokyny vo webe či súbore navádzajú AI na niečo, čo používateľ nežiadal.","also":["vloženie škodlivých pokynov","prompt injections"]},{"id":"ratelimit","g":"ai","word":"Limit počtu požiadaviek","text":"Najväčší počet požiadaviek na službu za určitý čas. Po prekročení musíš počkať.","also":["limity požiadaviek","limitu požiadaviek","rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Limit používania","text":"Koľko práce AI povoľuje tvoj plán za určité obdobie; potom sa práca pozastaví alebo stojí viac.","also":["limity používania","limitu používania","usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Tvorba softvéru najmä opisovaním požiadaviek AI, ktorá píše kód za teba.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Rozpočet","text":"Suma peňazí vyhradená na určitý účel.","also":["rozpočty","rozpočtu","budgets"],"noTip":1},{"id":"costest","g":"money","word":"Odhad nákladov","text":"Najlepší odhad ceny pred začiatkom práce.","also":["odhady nákladov","cost estimates"]},{"id":"roi","g":"money","word":"Návratnosť investície (ROI)","text":"Čo získaš v porovnaní s tým, čo vložíš. Kladná návratnosť znamená, že sa investícia oplatila.","also":["ROI"]},{"id":"tco","g":"money","word":"Celkové náklady vlastníctva (TCO)","text":"Všetky náklady počas životnosti, nielen nákup: prevádzka, podpora, aktualizácie aj vyradenie.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx a OpEx","text":"CapEx sú počiatočné výdavky na veci, ktoré si ponecháš; OpEx sú priebežné náklady, napríklad mesačné účty.","also":["CapEx","OpEx","kapitálové výdavky","prevádzkové výdavky","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Predplatné","text":"Pravidelné platby, zvyčajne mesačné či ročné, za možnosť ďalej niečo používať.","also":["predplatné","subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Softvér ako služba (SaaS)","text":"Softvér používaný online za predplatné, ktorého prevádzku zabezpečuje výrobca.","also":["SaaS"]},{"id":"payg","g":"money","word":"Platba podľa spotreby","text":"Platíš iba za využité služby, napríklad výpočty v cloude či tokeny AI.","also":["platba podľa spotreby","pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Nadlimitná spotreba","text":"Používanie nad rámec predplateného programu, za ktoré sa môže priplácať.","also":["nadlimitné poplatky","overages","overage charges"]},{"id":"billingalert","g":"money","word":"Upozornenie na výdavky","text":"Správa po dosiahnutí zvolenej úrovne výdavkov či spotreby. Varuje, ale nemusí zastaviť ďalšie účtovanie.","also":["upozornenia na výdavky","billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Bezplatný program","text":"Bezplatná úroveň platenej služby s obmedzeniami. Hodí sa na začiatok.","also":["bezplatný plán","free plan"]},{"id":"pricing","g":"money","word":"Cenový program","text":"Rôzne balíky služby, každý s vlastnou cenou a obmedzeniami.","also":["cenové programy","pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licencia","text":"Pravidlá používania, kopírovania, menenia či zdieľania cudzej tvorby, napríklad softvéru, písiem alebo obrázkov.","also":["licencie","licencií","licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source (otvorený zdrojový kód)","text":"Softvér, ktorého kód môže každý čítať, používať a často aj bezplatne meniť podľa licencie.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Licencia otvoreného kódu","text":"Pravidlá otvoreného kódu: niektoré povoľujú takmer všetko, napríklad MIT, iné vyžadujú zdieľať aj zmeny, napríklad GPL.","also":["licencie otvoreného kódu","open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietárny","text":"Vo vlastníctve firmy, bez voľného povolenia na kopírovanie či zmeny. Opak otvoreného kódu.","also":["proprietárny softvér","proprietary software"]},{"id":"copyright","g":"money","word":"Autorské právo","text":"Zákonné právo autora rozhodovať o kópiách svojho diela vrátane kódu a textu.","also":["chránený autorským právom","copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Duševné vlastníctvo (IP)","text":"Nápady a výtvory, ku ktorým zákon priznáva vlastnícke práva, napríklad kód, návrhy, názvy a logá.","also":["duševné vlastníctvo","intellectual property"]},{"id":"tos","g":"money","word":"Podmienky služby","text":"Pravidlá, s ktorými súhlasíš pri používaní služby.","also":["obchodné podmienky","podmienky používania","terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Zmluva","text":"Písomná dohoda dvoch strán vymáhateľná podľa zákona.","also":["zmluvy","zmluvu","zmlúv","contracts"],"noTip":1},{"id":"sow","g":"money","word":"Špecifikácia prác (SOW)","text":"Dokument presne určujúci, aká práca sa urobí, dokedy a za akú cenu.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Pevná cena","text":"Dohodnutá cena za celú prácu bez ohľadu na jej trvanie.","also":["pevná cena","fixed-price"]},{"id":"tm","g":"money","word":"Čas a materiál","text":"Platba za skutočne odpracované hodiny a použitý materiál namiesto pevnej ceny.","also":["T&M"]},{"id":"invoice","g":"money","word":"Faktúra","text":"Doklad žiadajúci úhradu za vykonanú prácu alebo dodaný tovar.","also":["faktúry","faktúr","invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Závislosť od dodávateľa","text":"Odchod od dodávateľa je taký ťažký či drahý, že pri ňom musíš zostať.","also":["závislosť od dodávateľa","lock-in"]},{"id":"procurement","g":"money","word":"Obstarávanie","text":"Výber dodávateľov a nakupovanie od nich."},{"id":"servicecredit","g":"money","word":"Kompenzačný kredit","text":"Vrátené peniaze či zľava pri nedodržaní dohody SLA dodávateľom.","also":["kompenzačné kredity","service credits"]}]}};
